-- Startcollectie van de bibliotheek, versie 1 (gegenereerd door scripts/startcollectie.mjs uit
-- data/startcollectie.json op 2026-11-27; niet met de hand wijzigen). Bestaande bronnen worden nooit overschreven.
-- Is de citeersleutel al bezet door een eigen bron, dan krijgt de startbron dezelfde sleutel met "st" erachter.
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'andersen-2022-psychosociaal-langdurig-verzuim', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'andersen2022') THEN 'andersen2022st' ELSE 'andersen2022' END, 'artikel', 'Combined psychosocial work factors and risk of long-term sickness absence in the general working population: Prospective cohort with register follow-up among 69 371 workers', '[{"achternaam":"Andersen","tussenvoegsel":"","voorletters":"L. L."},{"achternaam":"Vinstrup","tussenvoegsel":"","voorletters":"J."},{"achternaam":"Thorsen","tussenvoegsel":"","voorletters":"S. V."},{"achternaam":"Pedersen","tussenvoegsel":"","voorletters":"J."},{"achternaam":"Sundstrup","tussenvoegsel":"","voorletters":"E."},{"achternaam":"Rugulies","tussenvoegsel":"","voorletters":"R."}]', '', '', 2022, 'en', 'https://doi.org/10.5271/sjweh.4035', '10.5271/sjweh.4035', '{"tijdschrift":"Scandinavian Journal of Work, Environment & Health","jaargang":"48","nummer":"7","paginas":"549–559"}', '["verzuim","werkdruk"]', '[]', 'Prospectief cohortonderzoek onder 69.371 Deense werknemers, gekoppeld aan een register voor langdurig verzuim. Op basis van negen psychosociale werkfactoren zijn clusters gemaakt. Werknemers die op veel factoren tegelijk ongunstig scoorden, hadden een hoger risico op langdurig verzuim, het hoogst bij ongunstige scores op alle negen. Een of twee ongunstige factoren verhoogden het risico niet, zolang de overige factoren gunstig waren.', '["69.371 werknemers uit de Deense algemene beroepsbevolking (Work Environment and Health in Denmark, 2012-2018) werden tot twee jaar gevolgd in een register.","Het cluster met ongunstige scores op alle negen psychosociale factoren had het hoogste risico op langdurig verzuim (HR 1,68), vergeleken met het cluster met de gunstigste scores.","Een of twee ongunstige factoren verhoogden het risico niet bij verder gunstige scores; een combinatie van gunstige factoren lijkt beschermend.","De negen factoren waren erkenning, kwantitatieve eisen, werktempo, emotionele eisen, invloed, rechtvaardigheid, rolhelderheid, rolconflicten en steun van collega''s."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'andersen-2022-psychosociaal-langdurig-verzuim')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'andersen2022st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'angrave-et-al-2016-hr-analytics-kritisch', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'angrave2016') THEN 'angrave2016st' ELSE 'angrave2016' END, 'artikel', 'HR and analytics: why HR is set to fail the big data challenge', '[{"achternaam":"Angrave","tussenvoegsel":"","voorletters":"D."},{"achternaam":"Charlwood","tussenvoegsel":"","voorletters":"A."},{"achternaam":"Kirkpatrick","tussenvoegsel":"","voorletters":"I."},{"achternaam":"Lawrence","tussenvoegsel":"","voorletters":"M."},{"achternaam":"Stuart","tussenvoegsel":"","voorletters":"M."}]', '', '', 2016, 'en', 'https://doi.org/10.1111/1748-8583.12090', '10.1111/1748-8583.12090', '{"tijdschrift":"Human Resource Management Journal","jaargang":"26","nummer":"1","paginas":"1–11"}', '["hr-analytics"]', '[]', 'Kritisch artikel over HR-analytics en big data. De auteurs zetten vraagtekens bij optimistische verhalen dat HR-analytics een must-have is die de strategische rol van HR veiligstelt en de prestaties van organisaties verbetert. Zij stellen dat de huidige praktijk van HR-analytics waarschijnlijk geen ingrijpende verandering brengt, zolang de HR-beroepsgroep de mogelijkheden én de nadelen niet goed begrijpt en geen betere methoden ontwikkelt. Huidige trends kunnen HR zelfs definitief buiten de strategische invloed op bestuursniveau houden en de belangen van medewerkers schaden.', '["De auteurs betwisten het optimistische beeld van HR-analytics als onmisbaar middel voor een strategische rol van HR.","Zonder kennis van zowel de mogelijkheden als de nadelen, en zonder betere methoden, levert de huidige praktijk van HR-analytics waarschijnlijk geen echte verandering op.","Risico: huidige trends houden HR mogelijk buiten de strategische invloed op bestuursniveau, met weinig voordeel voor organisaties en actieve schade voor de belangen van medewerkers."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'angrave-et-al-2016-hr-analytics-kritisch')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'angrave2016st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'ap-2025-controle-werknemers', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'autoriteit2025') THEN 'autoriteit2025st' ELSE 'autoriteit2025' END, 'website', 'Voorwaarden voor controle werknemers', '[]', 'Autoriteit Persoonsgegevens', '', 2025, 'nl', 'https://www.autoriteitpersoonsgegevens.nl/themas/werk-en-uitkering/controle-van-werknemers/voorwaarden-voor-controle-werknemers', '', '{"datum":"2025-02-07","geraadpleegd":"2026-11-27"}', '["privacy","wetgeving","hr-processen"]', '[]', 'De Autoriteit Persoonsgegevens legt uit wanneer een werkgever werknemers mag controleren, bijvoorbeeld met volgsoftware, gps of camera''s. De werkgever heeft een grondslag nodig, moet kunnen laten zien dat controle echt nodig is en moet werknemers informeren over wat, waarom, wanneer en hoe er gecontroleerd wordt. Toestemming van werknemers is meestal geen goede grondslag, omdat zij een verzoek van hun werkgever moeilijk kunnen weigeren. Heeft de organisatie een OR, dan vraagt een regeling voor controle vooraf instemming van de OR, en bij grootschalige of stelselmatige monitoring moet eerst een DPIA worden gedaan.', '["Toestemming van werknemers is meestal geen bruikbare grondslag voor monitoring, omdat werknemers een verzoek van hun werkgever moeilijk kunnen weigeren.","Controle moet noodzakelijk zijn: het doel mag niet op een minder ingrijpende manier te bereiken zijn.","Heeft de organisatie een OR, dan mag een regeling voor controle niet zonder instemming van de OR worden ingevoerd.","Bij grootschalige of stelselmatige monitoring van werknemers moet de werkgever eerst een DPIA uitvoeren."]', 'redelijk', 'Informatie van een overheidsorganisatie.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'ap-2025-controle-werknemers')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'autoriteit2025st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'ap-2025-or-personeelsvolgsystemen', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'autoriteit2025b') THEN 'autoriteit2025bst' ELSE 'autoriteit2025b' END, 'website', 'De OR en personeelsvolgsystemen', '[]', 'Autoriteit Persoonsgegevens', '', 2025, 'nl', 'https://www.autoriteitpersoonsgegevens.nl/themas/werk-en-uitkering/ondernemingsraad/de-or-en-personeelsvolgsystemen', '', '{"datum":"2025-01-02","geraadpleegd":"2026-11-27"}', '["privacy","wetgeving","hr-analytics"]', '[]', 'De pagina legt uit wat een personeelsvolgsysteem is: een systeem waarmee aanwezigheid, gedrag of prestaties van werknemers te controleren zijn, ook als het daar nu niet voor wordt gebruikt. Voorbeelden zijn tijdregistratie, gps in auto''s, camera''s, maar ook workflow- of zaaksystemen en logging. De OR heeft instemmingsrecht bij een regeling voor zo''n systeem; zonder instemming mag de werkgever het systeem in principe niet gebruiken. De AP geeft toetsvragen die de OR kan stellen.', '["Ook een systeem dat werknemers zou kunnen volgen, maar dat daar nu niet voor wordt gebruikt, telt als personeelsvolgsysteem.","Gewone werksystemen kunnen een personeelsvolgsysteem zijn, zoals een workflow- of zaaksysteem.","De OR heeft instemmingsrecht (art. 27 lid 1 onder l WOR); zonder instemming mag de werkgever het systeem in principe niet gebruiken.","Een toetsvraag voor de OR is of personeelsbeoordeling alleen steunt op gegevens uit zo''n systeem."]', 'redelijk', 'Informatie van een overheidsorganisatie.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'ap-2025-or-personeelsvolgsystemen')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'autoriteit2025bst');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'ap-2025-pseudonimiseren', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'autoriteit2025c') THEN 'autoriteit2025cst' ELSE 'autoriteit2025c' END, 'website', 'Gegevens pseudonimiseren', '[]', 'Autoriteit Persoonsgegevens', '', 2025, 'nl', 'https://www.autoriteitpersoonsgegevens.nl/themas/basis-avg/beveiliging-van-persoonsgegevens/gegevens-pseudonimiseren', '', '{"datum":"2025-03-17","geraadpleegd":"2026-11-27"}', '["privacy","methode","hr-analytics"]', '[]', 'De AP legt uit dat pseudonimiseren een beveiligingsmaatregel is en niet hetzelfde als anonimiseren. Gepseudonimiseerde gegevens kunnen met aanvullende informatie nog naar personen te herleiden zijn; pseudonimiseren is een verwerking van persoonsgegevens, dus de AVG blijft gelden. Alleen namen weghalen is niet genoeg als de overige gegevens iemand toch herkenbaar maken. Ook gehashte gegevens zijn vaak niet anoniem.', '["Pseudonimiseren is geen anonimiseren: met aanvullende gegevens kan herleiding naar personen nog mogelijk zijn.","Een combinatie van een paar kenmerken kan al genoeg zijn om iemand te herkennen.","Alleen direct identificerende gegevens zoals namen weghalen is niet voldoende als de rest herleidbaar blijft.","Gepseudonimiseerde gegevens vallen onder de AVG en moeten goed beveiligd blijven."]', 'redelijk', 'Informatie van een overheidsorganisatie.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'ap-2025-pseudonimiseren')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'autoriteit2025cst');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'ap-2025-zieke-werknemers', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'autoriteit2025d') THEN 'autoriteit2025dst' ELSE 'autoriteit2025d' END, 'website', 'Regels voor werkgevers bij zieke werknemers', '[]', 'Autoriteit Persoonsgegevens', '', 2025, 'nl', 'https://www.autoriteitpersoonsgegevens.nl/themas/werk-en-uitkering/zieke-werknemers/regels-voor-werkgevers-bij-zieke-werknemers', '', '{"datum":"2025-01-02","geraadpleegd":"2026-11-27"}', '["verzuim","privacy","wetgeving"]', '[]', 'Volgens de AP mag een werkgever bij ziekte alleen vastleggen wat nodig is om het werk te regelen en de loondoorbetaling te beoordelen. Wat iemand mankeert en waardoor, zijn gezondheidsgegevens; daar mag de werkgever niet naar vragen en die mag hij niet vastleggen, ook niet als de werknemer het zelf vertelt. Ook toestemming van de werknemer maakt dit niet anders, op zeer uitzonderlijke gevallen na. De bedrijfsarts of arbodienst mag wel de verwachte duur en de belastbaarheid doorgeven, en een regeling over ziekteverzuim of re-integratie vraagt eerst instemming van de OR.', '["Gezondheidsgegevens zijn bijzondere persoonsgegevens; een werkgever mag niet vragen naar de aard of oorzaak van de ziekte.","Toestemming van de werknemer maakt dit in principe niet anders, omdat die door de afhankelijkheid niet vrij kan zijn; alleen in zeer uitzonderlijke gevallen (zoals ernstige suikerziekte of epilepsie) mag het met uitdrukkelijke toestemming wel.","Wel mag de werkgever onder meer vastleggen hoe lang de werknemer denkt dat de ziekte duurt.","Voor verzuimbeleid, de keuze van de arbodienst en het contract daarmee is vooraf instemming van de OR nodig."]', 'redelijk', 'Informatie van een overheidsorganisatie.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'ap-2025-zieke-werknemers')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'autoriteit2025dst');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'ap-2026-avg-in-het-kort', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'autoriteit2026c') THEN 'autoriteit2026cst' ELSE 'autoriteit2026c' END, 'website', 'De AVG in het kort', '[]', 'Autoriteit Persoonsgegevens', '', 2026, 'nl', 'https://www.autoriteitpersoonsgegevens.nl/themas/basis-avg/avg-algemeen/de-avg-in-het-kort', '', '{"datum":"2026-11-16","geraadpleegd":"2026-11-27"}', '["privacy","wetgeving"]', '[]', 'Deze pagina geeft een kort overzicht van de AVG, die sinds 25 mei 2018 in de hele EU geldt voor iedereen die persoonsgegevens verwerkt. De AP beschrijft de zes beginselen uit artikel 5 AVG, zoals doelbinding, dataminimalisatie en opslagbeperking, met de verantwoordingsplicht als overkoepelend zevende beginsel. Organisaties mogen bijvoorbeeld geen gegevens verzamelen omdat die misschien ooit handig zijn. De AP kan boetes en andere sancties opleggen bij overtreding.', '["Wie persoonsgegevens verwerkt, moet zich aan de beginselen houden en dat ook kunnen aantonen (verantwoordingsplicht).","Doelbinding: gegevens niet alvast verzamelen omdat ze misschien ooit van pas komen.","Dataminimalisatie: niet meer gegevens verwerken dan nodig is voor het doel.","Opslagbeperking: gegevens verwijderen zodra ze niet meer nodig zijn voor het oorspronkelijke doel."]', 'redelijk', 'Informatie van een overheidsorganisatie.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'ap-2026-avg-in-het-kort')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'autoriteit2026cst');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'ap-2026-dpia', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'autoriteit2026b') THEN 'autoriteit2026bst' ELSE 'autoriteit2026b' END, 'website', 'Data protection impact assessment (DPIA)', '[]', 'Autoriteit Persoonsgegevens', '', 2026, 'nl', 'https://www.autoriteitpersoonsgegevens.nl/themas/basis-avg/praktisch-avg/data-protection-impact-assessment-dpia', '', '{"datum":"2026-08-14","geraadpleegd":"2026-11-27"}', '["privacy","wetgeving","hr-analytics"]', '[]', 'Een DPIA is een verplichte risicoanalyse vooraf als een verwerking van persoonsgegevens waarschijnlijk een hoog privacyrisico oplevert. De AP beschrijft negen criteria van de Europese privacytoezichthouders; als vuistregel is een DPIA nodig als twee of meer daarvan gelden. Werknemers tellen daarbij als kwetsbare groep, omdat zij door de ongelijke machtsverhouding niet vrij toestemming kunnen geven of weigeren. De AP adviseert zo vroeg mogelijk te beginnen; heeft de organisatie een FG, dan moet die om advies worden gevraagd, en waar nodig ook de betrokkenen om hun mening.', '["Vuistregel: een DPIA is nodig als een verwerking aan twee of meer van de negen criteria voldoet.","Werknemers worden genoemd als voorbeeld van kwetsbare betrokkenen, door de ongelijke machtsverhouding.","Een DPIA bevat in ieder geval een beoordeling van noodzaak en proportionaliteit van de verwerking.","Een DPIA is geen eenmalige klus maar een doorlopend proces."]', 'redelijk', 'Informatie van een overheidsorganisatie.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'ap-2026-dpia')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'autoriteit2026bst');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'ap-2026-wat-zijn-persoonsgegevens', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'autoriteit2026') THEN 'autoriteit2026st' ELSE 'autoriteit2026' END, 'website', 'Wat zijn persoonsgegevens?', '[]', 'Autoriteit Persoonsgegevens', '', 2026, 'nl', 'https://www.autoriteitpersoonsgegevens.nl/themas/basis-avg/privacy-en-persoonsgegevens/wat-zijn-persoonsgegevens', '', '{"datum":"2026-09-16","geraadpleegd":"2026-11-27"}', '["privacy","wetgeving","methode"]', '[]', 'De AP legt uit dat persoonsgegevens alle informatie zijn over iemand die te identificeren is: de informatie gaat direct over iemand of is naar die persoon te herleiden. Voorbeelden zijn niet alleen naam en adres, maar ook klant- of personeelsnummers; ook gegevens die pas in combinatie met andere gegevens iets over iemand zeggen, zoals een IP-adres, kunnen persoonsgegevens zijn. Sommige gegevens, zoals over gezondheid of etnische afkomst, zijn bijzondere persoonsgegevens; die mag je alleen verwerken als er een wettelijke uitzondering is. Gegevens die alleen over een organisatie gaan, vallen niet onder de AVG, tenzij ze ook iets over een persoon zeggen.', '["Ook indirecte gegevens zijn persoonsgegevens: gegevens die in combinatie met andere gegevens iets zeggen over een persoon.","Personeelsnummers zijn een voorbeeld van persoonsgegevens.","Bijzondere persoonsgegevens, zoals gezondheid, mag je alleen verwerken als er een wettelijke uitzondering is."]', 'redelijk', 'Informatie van een overheidsorganisatie.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'ap-2026-wat-zijn-persoonsgegevens')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'autoriteit2026st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'arboportaal-2026-psa', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'ministerie2026') THEN 'ministerie2026st' ELSE 'ministerie2026' END, 'website', 'Psychosociale arbeidsbelasting (PSA)', '[]', 'Ministerie van Sociale Zaken en Werkgelegenheid', '', 2026, 'nl', 'https://www.arboportaal.nl/onderwerpen/psychosociale-arbeidsbelasting', '', '{"sitenaam":"Arboportaal","geraadpleegd":"2026-11-27"}', '["werkdruk","sociale-veiligheid","wetgeving"]', '[]', 'Arboportaal, de arbosite van het ministerie van SZW, legt uit dat PSA ontstaat door arbeidsrisico''s die stress veroorzaken: werkdruk en ongewenst gedrag, zoals pesten, agressie en geweld, discriminatie en (seksuele) intimidatie. PSA kan lichamelijke, psychische en sociale klachten geven. Werkgevers moeten daarom beleid voeren om PSA te voorkomen of te beperken, zoals artikel 2.15 van het Arbobesluit voorschrijft. Ook werknemers hebben een eigen verantwoordelijkheid voor veiligheid en gezondheid.', '["PSA ontstaat door werkdruk en ongewenst gedrag op de werkvloer.","De plicht van de werkgever om PSA-beleid te voeren staat in artikel 2.15 van het Arbobesluit.","Ook werknemers hebben een verantwoordelijkheid, voor hun eigen veiligheid en gezondheid en die van anderen.","Een sociaal veilige werkomgeving helpt PSA te voorkomen."]', 'redelijk', 'Informatie van een overheidsorganisatie.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'arboportaal-2026-psa')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'ministerie2026st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'arboportaal-2026-rie', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'ministerie2026b') THEN 'ministerie2026bst' ELSE 'ministerie2026b' END, 'website', 'Waaruit bestaat de RI&E?', '[]', 'Ministerie van Sociale Zaken en Werkgelegenheid', '', 2026, 'nl', 'https://www.arboportaal.nl/onderwerpen/arbowet--en--regelgeving/risico-inventarisatie---evaluatie/waaruit-bestaat-de-rie', '', '{"sitenaam":"Arboportaal","geraadpleegd":"2026-11-27"}', '["wetgeving","werkdruk","sociale-veiligheid"]', '[]', 'De RI&E is een schriftelijke inventarisatie van de risico''s voor gezondheid en veiligheid in een bedrijf. Vaste onderdelen zijn een overzicht van risico''s en al genomen maatregelen, een beoordeling en prioritering van de risico''s en een plan van aanpak met maatregelen, termijnen en verantwoordelijken. Werkgevers moeten de RI&E zo vaak bijwerken als nodig is. Als uit de RI&E blijkt dat risico''s zoals psychosociale arbeidsbelasting beter onderzocht moeten worden, is de werkgever verplicht dat te doen.', '["Een vast onderdeel van de RI&E is een beoordeling en prioritering van de risico''s.","Het plan van aanpak is verplicht: zonder plan van aanpak is de RI&E niet compleet.","Blijkt uit de RI&E dat een risico zoals PSA verdieping nodig heeft, dan moet de werkgever dat onderzoeken.","Werkgevers moeten de RI&E zo vaak aanpassen als nodig is."]', 'redelijk', 'Informatie van een overheidsorganisatie.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'arboportaal-2026-rie')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'ministerie2026bst');
