SELECT 'start', 'arthur-2003-effectiviteit-training', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'arthur2003') THEN 'arthur2003st' ELSE 'arthur2003' END, 'artikel', 'Effectiveness of training in organizations: A meta-analysis of design and evaluation features.', '[{"achternaam":"Arthur","tussenvoegsel":"","voorletters":"W."},{"achternaam":"Bennett","tussenvoegsel":"","voorletters":"W."},{"achternaam":"Edens","tussenvoegsel":"","voorletters":"P. S."},{"achternaam":"Bell","tussenvoegsel":"","voorletters":"S. T."}]', '', '', 2003, 'en', 'https://doi.org/10.1037/0021-9010.88.2.234', '10.1037/0021-9010.88.2.234', '{"tijdschrift":"Journal of Applied Psychology","jaargang":"88","nummer":"2","paginas":"234–245"}', '["ontwikkeling"]', '[]', 'Meta-analyse naar het verband tussen kenmerken van het ontwerp en de evaluatie van trainingen en hoe effectief trainingen in organisaties zijn. De gemiddelde effectgroottes liggen tussen d = 0,60 en d = 0,63, gemeten op vier niveaus: reacties van deelnemers, leren, gedrag en resultaten. Daarnaast hangen de trainingsmethode, de vaardigheid of taak die wordt getraind en de gekozen evaluatiecriteria samen met hoe effectief een training is.', '["Onderzocht is hoe kenmerken van het trainingsontwerp en de evaluatie samenhangen met de effectiviteit van trainingen in organisaties.","De gemiddelde effectgroottes zijn d = 0,60 voor reacties van deelnemers, 0,63 voor leren, 0,62 voor gedrag en 0,62 voor resultaten.","De trainingsmethode, de getrainde vaardigheid of taak en de keuze van evaluatiecriteria hangen samen met de effectiviteit van trainingsprogramma''s."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'arthur-2003-effectiviteit-training')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'arthur2003st');
