SELECT 'start', 'bakker-demerouti-2007-jdr', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'bakker2007') THEN 'bakker2007st' ELSE 'bakker2007' END, 'artikel', 'The Job Demands‐Resources model: state of the art', '[{"achternaam":"Bakker","tussenvoegsel":"","voorletters":"A. B."},{"achternaam":"Demerouti","tussenvoegsel":"","voorletters":"E."}]', '', '', 2007, 'en', 'https://doi.org/10.1108/02683940710733115', '10.1108/02683940710733115', '{"tijdschrift":"Journal of Managerial Psychology","jaargang":"22","nummer":"3","paginas":"309–328"}', '["werkdruk","tevredenheid"]', '[]', 'Overzichtsartikel over het Job Demands-Resources (JD-R) model. De auteurs bespreken eerst de sterke en zwakke punten van het demand-control-model en het effort-reward imbalance-model. Daarna introduceren zij het flexibelere JD-R model en de uitgangspunten ervan. Het model kijkt naar zowel negatieve als positieve indicatoren van welzijn en wordt expliciet gepresenteerd als hulpmiddel voor HRM. (Gebaseerd op het abstract.)', '["Het artikel geeft een state-of-the-art overzicht van het JD-R model.","Het demand-control-model en het effort-reward imbalance-model worden besproken op hun sterke en zwakke punten, vooral hun voorspellende waarde voor het welzijn van werknemers.","Het JD-R model kan dienen als HRM-instrument; een tweestapsaanpak brengt sterke en zwakke punten van individuen, teams, afdelingen en organisaties in beeld.","Het model richt zich op zowel negatieve als positieve indicatoren van welzijn."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'bakker-demerouti-2007-jdr')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'bakker2007st');
