SELECT 'start', 'bakker-demerouti-euwema-2005-buffer', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'bakker2005') THEN 'bakker2005st' ELSE 'bakker2005' END, 'artikel', 'Job Resources Buffer the Impact of Job Demands on Burnout.', '[{"achternaam":"Bakker","tussenvoegsel":"","voorletters":"A. B."},{"achternaam":"Demerouti","tussenvoegsel":"","voorletters":"E."},{"achternaam":"Euwema","tussenvoegsel":"","voorletters":"M. C."}]', '', '', 2005, 'en', 'https://doi.org/10.1037/1076-8998.10.2.170', '10.1037/1076-8998.10.2.170', '{"tijdschrift":"Journal of Occupational Health Psychology","jaargang":"10","nummer":"2","paginas":"170–180"}', '["werkdruk"]', '[]', 'Empirische studie die het JD-R model toetst en verfijnt. Aan het onderzoek namen 1.012 medewerkers van een grote instelling voor hoger onderwijs deel. Volgens het abstract dempen (bufferen) meerdere hulpbronnen de invloed van meerdere taakeisen op burn-out. (Gebaseerd op het abstract; lees de volledige tekst voor de precieze uitkomsten.)', '["De studie toetst en verfijnt het JD-R model.","Meerdere hulpbronnen dempen (bufferen) de invloed van meerdere taakeisen op burn-out.","Aan het onderzoek namen 1.012 medewerkers van een grote instelling voor hoger onderwijs deel."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'bakker-demerouti-euwema-2005-buffer')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'bakker2005st');
