SELECT 'start', 'barends-et-al-2017-evidence-based-management', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'barends2017') THEN 'barends2017st' ELSE 'barends2017' END, 'artikel', 'Managerial attitudes and perceived barriers regarding evidence-based practice: An international survey', '[{"achternaam":"Barends","tussenvoegsel":"","voorletters":"E."},{"achternaam":"Villanueva","tussenvoegsel":"","voorletters":"J."},{"achternaam":"Rousseau","tussenvoegsel":"","voorletters":"D. M."},{"achternaam":"Briner","tussenvoegsel":"","voorletters":"R. B."},{"achternaam":"Jepsen","tussenvoegsel":"","voorletters":"D. M."},{"achternaam":"Houghton","tussenvoegsel":"","voorletters":"E."},{"achternaam":"Have","tussenvoegsel":"ten","voorletters":"S."}]', '', '', 2017, 'en', 'https://doi.org/10.1371/journal.pone.0184594', '10.1371/journal.pone.0184594', '{"tijdschrift":"PLOS ONE","jaargang":"12","nummer":"10","artikelnummer":"e0184594"}', '["hr-analytics","methode"]', '[]', 'Internationale enquête onder managers, onder meer in Nederland en België, over hun houding tegenover evidence-based practice (EBP) en de drempels die ze ervaren. De meeste managers staan er positief tegenover, maar tijdgebrek en beperkt begrip van wetenschappelijk onderzoek zijn belangrijke drempels. Het artikel definieert EBP als besluiten nemen op basis van het beste beschikbare bewijs uit meerdere bronnen.', '["Evidence-based practice betekent besluiten nemen door zorgvuldig, expliciet en oordeelkundig gebruik te maken van het beste beschikbare bewijs uit meerdere bronnen.","In een enquête onder 2.789 managers in België, Nederland, de VS, het VK en Australië stonden de meeste managers positief tegenover EBP.","Tijdgebrek en beperkt begrip van wetenschappelijk onderzoek worden gezien als de belangrijkste drempels voor EBP in management."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'barends-et-al-2017-evidence-based-management')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'barends2017st');
