SELECT 'start', 'baruch-holtom-2008-responspercentages', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'baruch2008') THEN 'baruch2008st' ELSE 'baruch2008' END, 'artikel', 'Survey response rate levels and trends in organizational research', '[{"achternaam":"Baruch","tussenvoegsel":"","voorletters":"Y."},{"achternaam":"Holtom","tussenvoegsel":"","voorletters":"B. C."}]', '', '', 2008, 'en', 'https://doi.org/10.1177/0018726708094863', '10.1177/0018726708094863', '{"tijdschrift":"Human Relations","jaargang":"61","nummer":"8","paginas":"1139–1160"}', '["methode"]', '[]', 'Onderzoek naar de respons op enquêtes in organisatieonderzoek. De auteurs bekeken 1607 studies uit 2000 en 2005 in 17 wetenschappelijke tijdschriften, waarvan 490 met enquêtes. Bij enquêtes onder individuen was de gemiddelde respons 52,7%, bij enquêtes onder organisaties 35,7%. Beloningen (incentives) hingen niet samen met de respons, en digitale dataverzameling gaf minstens even veel respons als papieren post.', '["Gemiddelde respons in studies uit 2000 en 2005: 52,7% (standaarddeviatie 20,4) bij individuen en 35,7% (standaarddeviatie 18,8) bij organisaties.","De respons bleef in het decennium vóór het onderzoek vrij stabiel.","Incentives hingen niet samen met de respons; bij onderzoek onder organisaties gingen herinneringen juist samen met een lagere respons.","Dataverzameling via e-mail, telefoon of web gaf even hoge of hogere respons dan traditionele papieren post."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'baruch-holtom-2008-responspercentages')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'baruch2008st');
