SELECT 'start', 'bauer-2007-nieuwkomers-meta-analyse', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'bauer2007') THEN 'bauer2007st' ELSE 'bauer2007' END, 'artikel', 'Newcomer adjustment during organizational socialization: A meta-analytic review of antecedents, outcomes, and methods.', '[{"achternaam":"Bauer","tussenvoegsel":"","voorletters":"T. N."},{"achternaam":"Bodner","tussenvoegsel":"","voorletters":"T."},{"achternaam":"Erdogan","tussenvoegsel":"","voorletters":"B."},{"achternaam":"Truxillo","tussenvoegsel":"","voorletters":"D. M."},{"achternaam":"Tucker","tussenvoegsel":"","voorletters":"J. S."}]', '', '', 2007, 'en', 'https://doi.org/10.1037/0021-9010.92.3.707', '10.1037/0021-9010.92.3.707', '{"tijdschrift":"Journal of Applied Psychology","jaargang":"92","nummer":"3","paginas":"707–721"}', '["onboarding","vertrek"]', '[]', 'Meta-analyse met padmodellen over 70 unieke steekproeven van nieuwkomers. De aanpassing van nieuwkomers (rolhelderheid, vertrouwen in eigen kunnen en sociale acceptatie) blijkt het verband te dragen tussen socialisatietactieken en zelf informatie zoeken enerzijds, en uitkomsten als tevredenheid, betrokkenheid, prestaties, blijfintentie en verloop anderzijds. Het model werd in grote lijnen bevestigd. Daarnaast is gekeken of de onderzoeksmethode de resultaten beïnvloedt.', '["Het onderzoek is gebaseerd op 70 unieke steekproeven van nieuwkomers.","Rolhelderheid, vertrouwen in eigen kunnen en sociale acceptatie vormen de schakel tussen socialisatie (tactieken van de organisatie en zelf informatie zoeken) en de uitkomsten.","Tot de uitkomsten horen tevredenheid, betrokkenheid, prestaties, de intentie om te blijven en daadwerkelijk verloop.","De resultaten ondersteunden het voorgestelde model in grote lijnen."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'bauer-2007-nieuwkomers-meta-analyse')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'bauer2007st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'berthelsen-westerlund-bergstrom-burr-2020-copsoq-iii-zweden', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'berthelsen2020') THEN 'berthelsen2020st' ELSE 'berthelsen2020' END, 'artikel', 'Validation of the Copenhagen Psychosocial Questionnaire Version III and Establishment of Benchmarks for Psychosocial Risk Management in Sweden', '[{"achternaam":"Berthelsen","tussenvoegsel":"","voorletters":"H."},{"achternaam":"Westerlund","tussenvoegsel":"","voorletters":"H."},{"achternaam":"Bergström","tussenvoegsel":"","voorletters":"G."},{"achternaam":"Burr","tussenvoegsel":"","voorletters":"H."}]', '', '', 2020, 'en', 'https://doi.org/10.3390/ijerph17093179', '10.3390/ijerph17093179', '{"tijdschrift":"International Journal of Environmental Research and Public Health","jaargang":"17","nummer":"9","paginas":"3179"}', '["methode","statistiek","werkdruk"]', '[]', 'Validatiestudie van de Zweedse COPSOQ III op individueel niveau en op het niveau van de werkplek, met benchmarks voor psychosociaal risicomanagement. Met intraklassecorrelaties (ICC) is nagegaan of scores mogen worden samengevoegd tot werkplekniveau, en dat bleek gerechtvaardigd. De studie ondersteunt het gebruik van COPSOQ III voor metingen op werkplekniveau.', '["Twee steekproeven: een aselecte steekproef van Zweedse werknemers van 25–65 jaar (N = 2847) en een gemakssteekproef van niet-leidinggevende medewerkers op 51 werkplekken (N = 1818).","Met ICC(1) en ICC(2) is getoetst of individuele scores mogen worden samengevoegd tot werkplekniveau; de verklaarde variantie door de werkplek rechtvaardigde dat.","Betrouwbaarheid en schaalkenmerken waren, op enkele uitzonderingen na, voldoende op individueel en werkplekniveau; de studie levert benchmarks op."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'berthelsen-westerlund-bergstrom-burr-2020-copsoq-iii-zweden')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'berthelsen2020st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'bonilla-chaves-palos-sanchez-2023-hr-analytics-bibliometrie', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'bonillachaves2023') THEN 'bonillachaves2023st' ELSE 'bonillachaves2023' END, 'artikel', 'Exploring the Evolution of Human Resource Analytics: A Bibliometric Study', '[{"achternaam":"Bonilla-Chaves","tussenvoegsel":"","voorletters":"E. F."},{"achternaam":"Palos-Sánchez","tussenvoegsel":"","voorletters":"P. R."}]', '', '', 2023, 'en', 'https://doi.org/10.3390/bs13030244', '10.3390/bs13030244', '{"tijdschrift":"Behavioral Sciences","jaargang":"13","nummer":"3","paginas":"244"}', '["hr-analytics"]', '[]', 'Bibliometrische studie die de wetenschappelijke literatuur over HR-analytics in Scopus en Web of Science in kaart brengt (2008–2022). Na selectie bleven 218 artikelen over, die de auteurs analyseren op thema''s, citaties en ontwikkeling van het vakgebied. Ook geven ze een overzicht van eerdere reviews over HR-analytics.', '["Bibliometrische analyse van artikelen in Scopus en Web of Science uit 2008–2022: 331 artikelen gevonden, waarvan 218 na toepassing van de exclusiecriteria.","Volgens de auteurs is HR-analytics een nieuw en zich ontwikkelend vakgebied dat traditionele HR-praktijken kan veranderen.","HR-analytics kan via technologie HR-strategieën, organisatieprestaties en de ervaringen van mensen verbeteren.","Het artikel zet eerdere reviews op een rij, waaronder ''An evidence-based review of HR analytics'' en een review over de ethiek van people analytics."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'bonilla-chaves-palos-sanchez-2023-hr-analytics-bibliometrie')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'bonillachaves2023st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'brouwers-2015-vitaliteitsscan', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'brouwers2015') THEN 'brouwers2015st' ELSE 'brouwers2015' END, 'artikel', 'Development of a Vitality Scan related to workers'' sustainable employability: a study assessing its internal consistency and construct validity', '[{"achternaam":"Brouwers","tussenvoegsel":"","voorletters":"L. A. M."},{"achternaam":"Engels","tussenvoegsel":"","voorletters":"J. A."},{"achternaam":"Heerkens","tussenvoegsel":"","voorletters":"Y. F."},{"achternaam":"Beek","tussenvoegsel":"van der","voorletters":"A. J."}]', '', '', 2015, 'en', 'https://doi.org/10.1186/s12889-015-1894-z', '10.1186/s12889-015-1894-z', '{"tijdschrift":"BMC Public Health","jaargang":"15","nummer":"1","artikelnummer":"551"}', '["verzuim","methode"]', '[]', 'Het artikel beschrijft de ontwikkeling en eerste validering van een Vitaliteitsscan die signalen van stagnatie in het functioneren rond duurzame inzetbaarheid opspoort. Onder 1722 Nederlandse werknemers leverde de analyse vijf subschalen op met acceptabele tot goede betrouwbaarheid; de definitieve scan telt 28 items. Oudere werknemers rapporteerden de meeste problemen, maar er was geen verschil naar opleidingsniveau. De voorspellende waarde moet nog verder worden getest.', '["De scan is ontwikkeld en getest onder 1722 Nederlandse werknemers om signalen van stagnatie in het functioneren rond duurzame inzetbaarheid te meten.","Er kwamen vijf subschalen uit (Cronbachs alfa 0,72-0,87): balans en competentie, motivatie en betrokkenheid, veerkracht, mentale en fysieke gezondheid, en sociale steun op het werk.","Oudere werknemers rapporteerden de meeste problemen, jongere de minste; naar opleidingsniveau was er geen significant verschil.","De definitieve scan met 28 items had goede meeteigenschappen, maar de voorspellende waarde moet nog verder worden getest."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'brouwers-2015-vitaliteitsscan')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'brouwers2015st');
