SELECT 'start', 'burr-et-al-2019-copsoq-iii', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'burr2019') THEN 'burr2019st' ELSE 'burr2019' END, 'artikel', 'The Third Version of the Copenhagen Psychosocial Questionnaire', '[{"achternaam":"Burr","tussenvoegsel":"","voorletters":"H."},{"achternaam":"Berthelsen","tussenvoegsel":"","voorletters":"H."},{"achternaam":"Moncada","tussenvoegsel":"","voorletters":"S."},{"achternaam":"Nübling","tussenvoegsel":"","voorletters":"M."},{"achternaam":"Dupret","tussenvoegsel":"","voorletters":"E."},{"achternaam":"Demiral","tussenvoegsel":"","voorletters":"Y."},{"achternaam":"Oudyk","tussenvoegsel":"","voorletters":"J."},{"achternaam":"Kristensen","tussenvoegsel":"","voorletters":"T. S."},{"achternaam":"Llorens","tussenvoegsel":"","voorletters":"C."},{"achternaam":"Navarro","tussenvoegsel":"","voorletters":"A."},{"achternaam":"Lincke","tussenvoegsel":"","voorletters":"H.-J."},{"achternaam":"Bocéréan","tussenvoegsel":"","voorletters":"C."},{"achternaam":"Sahan","tussenvoegsel":"","voorletters":"C."},{"achternaam":"Smith","tussenvoegsel":"","voorletters":"P."},{"achternaam":"Pohrt","tussenvoegsel":"","voorletters":"A."}]', 'International COPSOQ Network', '', 2019, 'en', 'https://doi.org/10.1016/j.shaw.2019.10.002', '10.1016/j.shaw.2019.10.002', '{"tijdschrift":"Safety and Health at Work","jaargang":"10","nummer":"4","paginas":"482–503"}', '["methode","werkdruk"]', '[]', 'Beschrijving en psychometrische toetsing van de derde versie van de Copenhagen Psychosocial Questionnaire (COPSOQ III), een internationale vragenlijst over psychosociale arbeidsomstandigheden. De vragenlijst kent een verplichte set kernitems die in korte, middellange en lange nationale versies terugkomt. Bij de toetsing (2016–2017, zes landen) waren de meeste dimensies in de meeste landen voldoende betrouwbaar, en hingen de meeste dimensies laag tot middelmatig met elkaar samen.', '["COPSOQ III is ontwikkeld in reactie op trends in het werkende leven, theoretische concepten en internationale ervaring.","Kern van COPSOQ III is een vaste set verplichte kernitems die in nationale korte, middellange en lange versies moet zitten.","De vragenlijst is in 2016–2017 getest bij 23.361 werknemers in Canada, Spanje, Frankrijk, Duitsland, Zweden en Turkije.","De meeste dimensies hingen laag tot middelmatig met elkaar samen; de auteurs concluderen dat COPSOQ III betrouwbare en onderscheiden maten biedt."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'burr-et-al-2019-copsoq-iii')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'burr2019st');
