SELECT 'start', 'cbs-2025-baanwisselaars', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'cbs2025b') THEN 'cbs2025bst' ELSE 'cbs2025b' END, 'website', 'Minder werknemers stappen over naar een andere werkgever', '[]', 'Centraal Bureau voor de Statistiek', 'CBS', 2025, 'nl', 'https://www.cbs.nl/nl-nl/nieuws/2025/33/minder-werknemers-stappen-over-naar-een-andere-werkgever', '', '{"datum":"2025-08-14","geraadpleegd":"2026-11-27"}', '["vertrek"]', '[]', 'Dit CBS-bericht gaat over werknemers die van werkgever wisselen. In het tweede kwartaal van 2025 deed 3,8 procent van alle werknemers dat, minder dan drie jaar eerder toen de krapte op de arbeidsmarkt het grootst was. De meeste overstappers komen uit een flexibele arbeidsrelatie, en mensen die kort in dienst zijn wisselen het vaakst. Er zijn ook verschillen per beroepsgroep.', '["In het tweede kwartaal van 2025 wisselden 305 duizend werknemers van werkgever: 3,8 procent van alle werknemers. In hetzelfde kwartaal van 2022 was dat 4,7 procent.","In het tweede kwartaal van 2022, toen de krapte op de arbeidsmarkt het grootst was, waren er nog 358 duizend baanwisselaars. Sindsdien zijn de krapte en het aantal baanwisselaars allebei afgenomen.","62 procent van de baanwisselaars in het tweede kwartaal van 2025 kwam uit een flexibele arbeidsrelatie, 38 procent uit een vaste baan.","Werknemers die korter dan een jaar in dienst waren, wisselen het vaakst: 7,3 procent in het tweede kwartaal van 2025, tegen 9,4 procent drie jaar eerder."]', 'hoog', 'Officiële statistiek van het CBS.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'cbs-2025-baanwisselaars')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'cbs2025bst');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'cbs-2025-cao-lonen', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'cbs2025') THEN 'cbs2025st' ELSE 'cbs2025' END, 'website', 'Cao-lonen stijgen in 2025 met 5,0 procent', '[]', 'Centraal Bureau voor de Statistiek', 'CBS', 2025, 'nl', 'https://www.cbs.nl/nl-nl/nieuws/2026/01/cao-lonen-stijgen-in-2025-met-5-0-procent', '', '{"datum":"2025-12-31","geraadpleegd":"2026-11-27"}', '["arbeidsvoorwaarden"]', '[]', 'Het CBS meldt dat de cao-lonen in 2025 gemiddeld 5,0 procent hoger waren dan in 2024. Dat is minder dan in 2023 en 2024, maar nog steeds een van de hoogste stijgingen in veertig jaar. Na correctie voor inflatie stegen de lonen 1,6 procent. Bij de overheid stegen de cao-lonen het minst.', '["In 2025 lagen de cao-lonen gemiddeld 5,0 procent hoger dan in 2024 (voorlopig cijfer). Na correctie voor inflatie was de stijging 1,6 procent.","De stijging was lager dan in 2023 (6,1 procent) en 2024 (6,5 procent), maar een van de hoogste in de afgelopen veertig jaar.","In 2025 stegen de cao-lonen bij de overheid (3,9 procent) minder dan bij gesubsidieerde instellingen (4,8 procent) en particuliere bedrijven (5,3 procent).","De stijging neemt af: in het vierde kwartaal van 2025 lagen de cao-lonen 4,6 procent hoger dan een jaar eerder, tegen 6,8 procent in het derde kwartaal van 2024."]', 'hoog', 'Officiële statistiek van het CBS.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'cbs-2025-cao-lonen')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'cbs2025st');
