SELECT 'start', 'cbs-2026-statline-ziekteverzuim', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'cbs2026b') THEN 'cbs2026bst' ELSE 'cbs2026b' END, 'cijfers', 'Ziekteverzuimpercentage; bedrijfstakken (SBI 2008) en bedrijfsgrootte', '[]', 'Centraal Bureau voor de Statistiek', 'CBS', 2026, 'nl', 'https://www.cbs.nl/nl-nl/cijfers/detail/80072ned', '', '{"geraadpleegd":"2026-11-27"}', '["verzuim"]', '[]', 'Deze CBS-tabel geeft het ziekteverzuimpercentage van werknemers bij bedrijven en overheid, per bedrijfstak en per bedrijfsgrootte. Het verzuim wordt gemeten als ziektedagen in procenten van de beschikbare dagen, inclusief verzuim langer dan een jaar. Over heel 2025 was het verzuim 5,4%; in het derde kwartaal van 2026 was het (voorlopig) 5,3%. Van de hoofdbedrijfstakken had de zorg in 2025 het hoogste verzuim en de horeca het laagste, en het verzuim is hoger naarmate bedrijven groter zijn.', '["Over heel 2025 was het ziekteverzuim van werknemers in alle bedrijfstakken samen 5,4% (definitief cijfer).","Van de hoofdbedrijfstakken had de gezondheids- en welzijnszorg in 2025 het hoogste verzuim (7,5%) en de horeca het laagste (3,2%). Binnen de zorg lag het verzuim in de verpleging en zorg met overnachting nog hoger (8,8%).","Hoe groter het bedrijf, hoe hoger het verzuim: in 2025 2,6% bij 1 tot 10, 4,7% bij 10 tot 100 en 6,3% bij 100 of meer werkzame personen.","Het verzuimpercentage telt verzuim van langer dan een jaar wel mee, maar zwangerschaps- en bevallingsverlof niet."]', 'hoog', 'Officiële statistiek van het CBS.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'cbs-2026-statline-ziekteverzuim')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'cbs2026bst');
