SELECT 'start', 'chassang-2017-avg-wetenschappelijk-onderzoek', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'chassang2017') THEN 'chassang2017st' ELSE 'chassang2017' END, 'artikel', 'The impact of the EU general data protection regulation on scientific research', '[{"achternaam":"Chassang","tussenvoegsel":"","voorletters":"G."}]', '', '', 2017, 'en', 'https://doi.org/10.3332/ecancer.2017.709', '10.3332/ecancer.2017.709', '{"tijdschrift":"ecancermedicalscience","jaargang":"11","artikelnummer":"709"}', '["wetgeving","privacy"]', '[]', 'Overzicht van wat de AVG (Verordening (EU) 2016/679) betekent voor wetenschappelijk onderzoek met persoonsgegevens. Het artikel legt begrippen uit als pseudonimisering, anonieme gegevens en toestemming, en bespreekt de beginselen en procedures, zoals privacy by design en by default. Het richt zich op gezondheidsonderzoek, maar de begrippen gelden voor elk onderzoek met persoonsgegevens.', '["Gepseudonimiseerde gegevens blijven persoonsgegevens; de extra informatie om personen te herleiden moet apart en beveiligd worden bewaard.","Echt anonieme gegevens vallen niet onder de AVG, ook niet bij gebruik voor statistiek of onderzoek.","Persoonsgegevens moeten voor welbepaalde, uitdrukkelijk omschreven en gerechtvaardigde doelen worden verzameld en beperkt blijven tot wat nodig is; standaard worden alleen de noodzakelijke gegevens verwerkt.","Toestemming moet vrij, specifiek, geïnformeerd en ondubbelzinnig zijn."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'chassang-2017-avg-wetenschappelijk-onderzoek')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'chassang2017st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'cohen-1992-power-primer', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'cohen1992') THEN 'cohen1992st' ELSE 'cohen1992' END, 'artikel', 'A power primer.', '[{"achternaam":"Cohen","tussenvoegsel":"","voorletters":"J."}]', '', '', 1992, 'en', 'https://doi.org/10.1037/0033-2909.112.1.155', '10.1037/0033-2909.112.1.155', '{"tijdschrift":"Psychological Bulletin","jaargang":"112","nummer":"1","paginas":"155–159"}', '["statistiek","methode"]', '[]', 'Artikel dat poweranalyse toegankelijker wil maken voor gedragswetenschappers. Cohen geeft een handzaam overzicht van benodigde steekproefgroottes en conventionele waarden voor kleine, middelgrote en grote effecten.', '["Volgens Cohen wordt poweranalyse in gedragswetenschappelijk onderzoek verwaarloosd, mogelijk doordat de standaardliteratuur ontoegankelijk of moeilijk is.","Het artikel geeft een handzaam, niet uitputtend overzicht van benodigde steekproefgroottes.","Het geeft effectgrootte-indexen met conventionele waarden voor kleine, middelgrote en grote effecten."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'cohen-1992-power-primer')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'cohen1992st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'colquitt-2001-organisatierechtvaardigheid', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'colquitt2001') THEN 'colquitt2001st' ELSE 'colquitt2001' END, 'artikel', 'Justice at the millennium: A meta-analytic review of 25 years of organizational justice research.', '[{"achternaam":"Colquitt","tussenvoegsel":"","voorletters":"J. A."},{"achternaam":"Conlon","tussenvoegsel":"","voorletters":"D. E."},{"achternaam":"Wesson","tussenvoegsel":"","voorletters":"M. J."},{"achternaam":"Porter","tussenvoegsel":"","voorletters":"C. O. L. H."},{"achternaam":"Ng","tussenvoegsel":"","voorletters":"K. Y."}]', '', '', 2001, 'en', 'https://doi.org/10.1037/0021-9010.86.3.425', '10.1037/0021-9010.86.3.425', '{"tijdschrift":"Journal of Applied Psychology","jaargang":"86","nummer":"3","paginas":"425–445"}', '["hr-processen"]', '[]', 'Meta-analytisch overzicht van 183 studies uit 25 jaar onderzoek naar ervaren rechtvaardigheid in organisaties. Het artikel gaat in op hoe sterk de verschillende vormen van rechtvaardigheid met elkaar samenhangen, welke rechtvaardigheidscriteria het zwaarst wegen en wat elke vorm afzonderlijk bijdraagt aan belangrijke uitkomsten. Daarbij worden vier vormen onderscheiden: verdelende, procedurele, interpersoonlijke en informationele rechtvaardigheid.', '["Het artikel is een meta-analytisch overzicht van 183 studies naar rechtvaardigheid in organisaties.","Het behandelt de samenhang tussen rechtvaardigheidsdimensies, het relatieve belang van rechtvaardigheidscriteria en de unieke effecten van elke dimensie op belangrijke uitkomsten.","De resultaten laten de algemene en unieke samenhang zien van verdelende, procedurele, interpersoonlijke en informationele rechtvaardigheid met uitkomsten in organisaties."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'colquitt-2001-organisatierechtvaardigheid')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'colquitt2001st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'cook-dickinson-eccles-2009-respons-postenquetes', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'cook2009') THEN 'cook2009st' ELSE 'cook2009' END, 'artikel', 'Response rates in postal surveys of healthcare professionals between 1996 and 2005: An observational study', '[{"achternaam":"Cook","tussenvoegsel":"","voorletters":"J. V."},{"achternaam":"Dickinson","tussenvoegsel":"","voorletters":"H. O."},{"achternaam":"Eccles","tussenvoegsel":"","voorletters":"M. P."}]', '', '', 2009, 'en', 'https://doi.org/10.1186/1472-6963-9-160', '10.1186/1472-6963-9-160', '{"tijdschrift":"BMC Health Services Research","jaargang":"9","nummer":"1","artikelnummer":"160"}', '["methode"]', '[]', 'Observationele studie naar responspercentages in enquêtes onder zorgprofessionals, gepubliceerd tussen 1996 en 2005. Op basis van 350 studies schatten de auteurs de gemiddelde respons, kijken ze naar factoren die de respons verhogen en naar hoe vaak non-responsvertekening werd onderzocht. Herinneringen verhoogden de respons, maar non-responsanalyse bleef meestal achterwege.', '["In 350 studies (publicaties 1996–2005) was de gemiddelde respons onder artsen 57,5%, significant lager dan in de tien jaar daarvoor.","Herinneringen versturen ging samen met een hogere respons (aangepaste OR 1,3), maar slechts de helft van de studies deed dat.","Slechts 17% van de studies onderzocht mogelijke non-responsvertekening; de auteurs adviseren herinneringen en een non-responsanalyse als vaste werkwijze."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'cook-dickinson-eccles-2009-respons-postenquetes')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'cook2009st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'crawford-lepine-rich-2010-jdr-meta', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'crawford2010') THEN 'crawford2010st' ELSE 'crawford2010' END, 'artikel', 'Linking job demands and resources to employee engagement and burnout: A theoretical extension and meta-analytic test.', '[{"achternaam":"Crawford","tussenvoegsel":"","voorletters":"E. R."},{"achternaam":"LePine","tussenvoegsel":"","voorletters":"J. A."},{"achternaam":"Rich","tussenvoegsel":"","voorletters":"B. L."}]', '', '', 2010, 'en', 'https://doi.org/10.1037/a0019364', '10.1037/a0019364', '{"tijdschrift":"Journal of Applied Psychology","jaargang":"95","nummer":"5","paginas":"834–848"}', '["werkdruk","tevredenheid"]', '[]', 'Meta-analytische studie die het JD-R model uitbreidt met theorie over hoe werknemers stressoren beoordelen (appraisal). Daarmee willen de auteurs verklaren waarom de relatie tussen taakeisen en bevlogenheid in eerder onderzoek inconsistent was. De herziene theorie is getoetst met meta-analytische structurele modellen. In deze sessie was alleen een ingekort abstract beschikbaar; de precieze uitkomsten zijn niet gecontroleerd.', '["Het artikel breidt het JD-R model uit met theorie over de beoordeling van stressoren, om inconsistente verbanden tussen taakeisen en bevlogenheid te verklaren.","De herziene theorie wordt getoetst met meta-analytische structurele modellering."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'crawford-lepine-rich-2010-jdr-meta')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'crawford2010st');
