SELECT 'start', 'cronbach-1951-coefficient-alpha', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'cronbach1951') THEN 'cronbach1951st' ELSE 'cronbach1951' END, 'artikel', 'Coefficient Alpha and the Internal Structure of Tests', '[{"achternaam":"Cronbach","tussenvoegsel":"","voorletters":"L. J."}]', '', '', 1951, 'en', 'https://doi.org/10.1007/BF02310555', '10.1007/BF02310555', '{"tijdschrift":"Psychometrika","jaargang":"16","nummer":"3","paginas":"297–334"}', '["methode","statistiek"]', '[]', 'Artikel waarin Cronbach een algemene formule beschrijft: coëfficiënt alfa (α). De Kuder-Richardson-coëfficiënt is daar een speciaal geval van. Cronbach laat zien dat alfa het gemiddelde is van alle mogelijke split-half-coëfficiënten van een test, en dus schat hoe sterk twee willekeurige sets vergelijkbare items met elkaar samenhangen. Een test die uit duidelijk verschillende onderdelen bestaat, moet je volgens hem eerst opsplitsen voordat je alfa berekent.', '["Alfa is het gemiddelde van alle split-half-coëfficiënten van een test en schat de correlatie tussen twee willekeurige sets items van hetzelfde soort.","Alfa is een geschikte maat voor hoe gelijkwaardig de items zijn en, behalve bij heel korte tests, voor hoe sterk de test op één hoofdfactor is gericht.","Bestaat een test uit duidelijk verschillende deeltests (deelschalen)? Splits die dan eerst op voordat je de formule gebruikt.","Bij het ontwerpen van een test zijn scores het best te interpreteren als elke apart gescoorde deelschaal sterk op één factor is gericht en geen grote clusters van items met een eigen (groeps)factor bevat."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'cronbach-1951-coefficient-alpha')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'cronbach1951st');
