SELECT 'start', 'demerouti-bakker-nachreiner-schaufeli-2001-jdr-burnout', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'demerouti2001') THEN 'demerouti2001st' ELSE 'demerouti2001' END, 'artikel', 'The job demands-resources model of burnout.', '[{"achternaam":"Demerouti","tussenvoegsel":"","voorletters":"E."},{"achternaam":"Bakker","tussenvoegsel":"","voorletters":"A. B."},{"achternaam":"Nachreiner","tussenvoegsel":"","voorletters":"F."},{"achternaam":"Schaufeli","tussenvoegsel":"","voorletters":"W. B."}]', '', '', 2001, 'en', 'https://doi.org/10.1037/0021-9010.86.3.499', '10.1037/0021-9010.86.3.499', '{"tijdschrift":"Journal of Applied Psychology","jaargang":"86","nummer":"3","paginas":"499–512"}', '["werkdruk","methode"]', '[]', 'Het oorspronkelijke artikel waarin het JD-R model wordt geïntroduceerd. Werkkenmerken worden ingedeeld in taakeisen en hulpbronnen, en die hangen elk met andere uitkomsten samen. De auteurs gebruikten zelfrapportages en beoordelingen door observatoren in drie beroepsgroepen (totaal N = 374). Taakeisen hingen vooral samen met uitputting, een gebrek aan hulpbronnen vooral met disengagement (afstand nemen van het werk). Ook werd de tweefactorstructuur van de Oldenburg Burnout Inventory bevestigd. (Gebaseerd op het abstract.)', '["Werkomstandigheden zijn in te delen in twee brede categorieën: taakeisen en hulpbronnen.","Taakeisen hangen vooral samen met de uitputtingscomponent van burn-out, (een gebrek aan) hulpbronnen vooral met disengagement.","Het patroon was zeer vergelijkbaar in drie beroepsgroepen (dienstverlening, industrie, transport; totaal N = 374).","De Oldenburg Burnout Inventory (OLBI) bleek een tweefactorstructuur te hebben: uitputting en disengagement."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'demerouti-bakker-nachreiner-schaufeli-2001-jdr-burnout')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'demerouti2001st');
