SELECT 'start', 'dunn-baguley-brunsden-2014-alpha-omega', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'dunn2014') THEN 'dunn2014st' ELSE 'dunn2014' END, 'artikel', 'From alpha to omega: A practical solution to the pervasive problem of internal consistency estimation', '[{"achternaam":"Dunn","tussenvoegsel":"","voorletters":"T. J."},{"achternaam":"Baguley","tussenvoegsel":"","voorletters":"T."},{"achternaam":"Brunsden","tussenvoegsel":"","voorletters":"V."}]', '', '', 2014, 'en', 'https://doi.org/10.1111/bjop.12046', '10.1111/bjop.12046', '{"tijdschrift":"British Journal of Psychology","jaargang":"105","nummer":"3","paginas":"399–412"}', '["statistiek"]', '[]', 'De auteurs wijzen erop dat alpha de populairste betrouwbaarheidsmaat is, terwijl de psychometrische literatuur veel tekortkomingen beschrijft. Ze bepleiten een overstap naar coëfficiënt omega. Ook geven ze een korte handleiding om omega met een betrouwbaarheidsinterval te berekenen in gratis open-source software.', '["Alpha is de meest gerapporteerde betrouwbaarheidsmaat in psychologisch onderzoek, ondanks talrijke gedocumenteerde tekortkomingen.","De auteurs bepleiten de overstap van alpha naar omega en laten zien hoe je puntschattingen en intervalschattingen van omega berekent met gratis open-source software."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'dunn-baguley-brunsden-2014-alpha-omega')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'dunn2014st');
