SELECT 'start', 'edmondson-1999-psychological-safety', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'edmondson1999') THEN 'edmondson1999st' ELSE 'edmondson1999' END, 'artikel', 'Psychological Safety and Learning Behavior in Work Teams', '[{"achternaam":"Edmondson","tussenvoegsel":"","voorletters":"A."}]', '', '', 1999, 'en', 'https://doi.org/10.2307/2666999', '10.2307/2666999', '{"tijdschrift":"Administrative Science Quarterly","jaargang":"44","nummer":"2","paginas":"350–383"}', '["sociale-veiligheid","leiderschap"]', '[]', 'Het artikel introduceert het begrip teampsychologische veiligheid: de gedeelde overtuiging in een team dat het veilig is om interpersoonlijke risico''s te nemen. In een veldstudie bij 51 werkteams in een productiebedrijf hing psychologische veiligheid samen met leergedrag, en leergedrag medieerde de relatie tussen psychologische veiligheid en teamprestaties. Zowel teamstructuren (zoals ondersteunende context en coaching door de leidinggevende) als gedeelde overtuigingen beïnvloeden teamuitkomsten.', '["Teampsychologische veiligheid is de gedeelde overtuiging dat het team veilig is voor interpersoonlijk risico nemen.","In 51 werkteams hing psychologische veiligheid samen met leergedrag; team-efficacy deed dat niet na controle voor psychologische veiligheid.","Leergedrag medieert de relatie tussen psychologische veiligheid en teamprestaties.","Zowel teamstructuren (ondersteunende context, coaching door de teamleider) als gedeelde overtuigingen bepalen teamuitkomsten."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'edmondson-1999-psychological-safety')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'edmondson1999st');
