SELECT 'start', 'griffeth-hom-gaertner-2000-verloop-meta-analyse', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'griffeth2000') THEN 'griffeth2000st' ELSE 'griffeth2000' END, 'artikel', 'A Meta-Analysis of Antecedents and Correlates of Employee Turnover: Update, Moderator Tests, and Research Implications for the Next Millennium', '[{"achternaam":"Griffeth","tussenvoegsel":"","voorletters":"R. W."},{"achternaam":"Hom","tussenvoegsel":"","voorletters":"P. W."},{"achternaam":"Gaertner","tussenvoegsel":"","voorletters":"S."}]', '', '', 2000, 'en', 'https://doi.org/10.1177/014920630002600305', '10.1177/014920630002600305', '{"tijdschrift":"Journal of Management","jaargang":"26","nummer":"3","paginas":"463–488"}', '["vertrek"]', '[]', 'Uitgebreide meta-analyse naar voorspellers en correlaten van personeelsverloop. Het is een actualisering van de eerdere meta-analyse van Hom en Griffeth (1995). Bij verschijnen gold dit als het breedste kwantitatieve overzicht van hoe sterk uiteenlopende factoren verloop voorspellen. Ook is onderzocht onder welke omstandigheden die verbanden sterker of zwakker zijn.', '["Het artikel actualiseert en verbreedt de meta-analyse van Hom en Griffeth (1995).","Bij verschijnen was het het breedste kwantitatieve overzicht van de voorspellende kracht van een groot aantal verloopfactoren.","De studie brengt factoren in kaart die de samenhang tussen voorspellers en verloop beïnvloeden (moderatoren)."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'griffeth-hom-gaertner-2000-verloop-meta-analyse')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'griffeth2000st');
