SELECT 'start', 'harter-schmidt-hayes-2002-engagement-outcomes', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'harter2002') THEN 'harter2002st' ELSE 'harter2002' END, 'artikel', 'Business-unit-level relationship between employee satisfaction, employee engagement, and business outcomes: A meta-analysis.', '[{"achternaam":"Harter","tussenvoegsel":"","voorletters":"J. K."},{"achternaam":"Schmidt","tussenvoegsel":"","voorletters":"F. L."},{"achternaam":"Hayes","tussenvoegsel":"","voorletters":"T. L."}]', '', '', 2002, 'en', 'https://doi.org/10.1037/0021-9010.87.2.268', '10.1037/0021-9010.87.2.268', '{"tijdschrift":"Journal of Applied Psychology","jaargang":"87","nummer":"2","paginas":"268–279"}', '["tevredenheid","hr-analytics"]', '[]', 'Meta-analyse op het niveau van bedrijfsonderdelen naar de relatie tussen medewerkerstevredenheid/-betrokkenheid en bedrijfsuitkomsten zoals klanttevredenheid, productiviteit, winst en personeelsverloop. De analyse omvat 7.939 bedrijfsonderdelen in 36 bedrijven. In deze sessie was alleen een ingekort abstract beschikbaar; de omvang en richting van de gevonden verbanden zijn niet gecontroleerd.', '["De meta-analyse is gebaseerd op 7.939 bedrijfsonderdelen in 36 bedrijven.","Onderzocht is de relatie op afdelings-/vestigingsniveau tussen tevredenheid-betrokkenheid en uitkomsten als klanttevredenheid, productiviteit, winst en personeelsverloop."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'harter-schmidt-hayes-2002-engagement-outcomes')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'harter2002st');
