SELECT 'start', 'hartnell-ou-kinicki-2011-cultuur-effectiviteit', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'hartnell2011') THEN 'hartnell2011st' ELSE 'hartnell2011' END, 'artikel', 'Organizational culture and organizational effectiveness: A meta-analytic investigation of the competing values framework''s theoretical suppositions', '[{"achternaam":"Hartnell","tussenvoegsel":"","voorletters":"C. A."},{"achternaam":"Ou","tussenvoegsel":"","voorletters":"A. Y."},{"achternaam":"Kinicki","tussenvoegsel":"","voorletters":"A."}]', '', '', 2011, 'en', 'https://doi.org/10.1037/a0021987', '10.1037/a0021987', '{"tijdschrift":"Journal of Applied Psychology","jaargang":"96","nummer":"4","paginas":"677–694"}', '["cultuur"]', '[]', 'Meta-analyse over de samenhang tussen organisatiecultuur en de effectiviteit van organisaties. De auteurs gebruiken het Competing Values Framework (CVF) van Quinn en Rohrbaugh (1983) als indeling en onderzoeken de samenhang tussen 3 cultuurtypen en 3 hoofdmaten van effectiviteit, onder meer houdingen van medewerkers en operationele prestaties. Op basis van 84 studies met 94 onafhankelijke steekproeven hangen clan-, adhocratie- en marktcultuur elk op een eigen manier positief samen met effectiviteit, maar niet altijd zoals verwacht. Het CVF zelf krijgt maar gedeeltelijk steun.', '["Het onderzoek gaat over de samenhang tussen 3 cultuurtypen uit het CVF en 3 hoofdmaten van effectiviteit, waaronder houdingen van medewerkers en operationele prestaties.","Clan-, adhocratie- en marktcultuur hangen verschillend en positief samen met de effectiviteitsmaten, maar niet altijd zoals voorspeld (84 studies, 94 onafhankelijke steekproeven).","Het CVF krijgt gemengde steun: delen van de voorgestelde interne structuur van het model worden niet bevestigd."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'hartnell-ou-kinicki-2011-cultuur-effectiviteit')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'hartnell2011st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'hazelzet-2019-di-interventies', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'hazelzet2019') THEN 'hazelzet2019st' ELSE 'hazelzet2019' END, 'artikel', 'Effectiveness of Interventions to Promote Sustainable Employability: A Systematic Review', '[{"achternaam":"Hazelzet","tussenvoegsel":"","voorletters":"E."},{"achternaam":"Picco","tussenvoegsel":"","voorletters":"E."},{"achternaam":"Houkes","tussenvoegsel":"","voorletters":"I."},{"achternaam":"Bosma","tussenvoegsel":"","voorletters":"H."},{"achternaam":"Rijk","tussenvoegsel":"de","voorletters":"A."}]', '', '', 2019, 'en', 'https://doi.org/10.3390/ijerph16111985', '10.3390/ijerph16111985', '{"tijdschrift":"International Journal of Environmental Research and Public Health","jaargang":"16","nummer":"11","paginas":"1985"}', '["verzuim"]', '[]', 'Systematische review naar de effectiviteit van door werkgevers geïnitieerde interventies voor duurzame inzetbaarheid. Duurzame inzetbaarheid is hier opgevat als vier kerncomponenten: gezondheid, productiviteit, waardevol werk en langetermijnperspectief. Van 596 gevonden artikelen bleven 7 studies over, van matige tot zwakke kwaliteit. Positieve effecten werden gevonden op uitkomsten rond waardevol werk, dat essentieel leek voor effectieve interventies.', '["Duurzame inzetbaarheid wordt omschreven met vier kerncomponenten: gezondheid, productiviteit, waardevol werk en langetermijnperspectief.","Van 596 artikelen werden 7 studies opgenomen, met matige tot zwakke methodologische kwaliteit.","Positieve effecten werden gevonden op uitkomsten rond waardevol werk; deze component leek essentieel voor effectieve interventies.","Er zijn evaluatiestudies van hogere kwaliteit nodig."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'hazelzet-2019-di-interventies')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'hazelzet2019st');
