SELECT 'start', 'hendra-hill-2019-response-rates', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'hendra2019') THEN 'hendra2019st' ELSE 'hendra2019' END, 'artikel', 'Rethinking Response Rates: New Evidence of Little Relationship Between Survey Response Rates and Nonresponse Bias', '[{"achternaam":"Hendra","tussenvoegsel":"","voorletters":"R."},{"achternaam":"Hill","tussenvoegsel":"","voorletters":"A."}]', '', '', 2019, 'en', 'https://doi.org/10.1177/0193841X18807719', '10.1177/0193841X18807719', '{"tijdschrift":"Evaluation Review","jaargang":"43","nummer":"5","paginas":"307–330"}', '["methode"]', '[]', 'Onderzoek naar de vraag of een hoge respons (in Amerikaans door de overheid gefinancierd evaluatieonderzoek vaak 80%) nodig is om non-responsvertekening te beperken. De auteurs vinden nauwelijks verband tussen respons en vertekening, en laten zien dat het najagen van een hoge respons de veldwerkperiode verlengt. Volgens hen kan het geld beter naar methoden en technieken die meer effect hebben.', '["Federaal gefinancierd evaluatieonderzoek in de VS streeft doorgaans naar 80% respons; de auteurs vragen zich af of die drempel nodig is.","Er bleek weinig verband tussen de hoogte van de respons en non-responsvertekening.","Een hoge respons najagen verlengt de veldwerkperiode, wat andere meetproblemen kan geven, en kost geld dat mogelijk beter aan andere methoden en technieken besteed kan worden."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'hendra-hill-2019-response-rates')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'hendra2019st');
