SELECT 'start', 'herscovitch-meyer-2002-commitment-verandering', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'herscovitch2002') THEN 'herscovitch2002st' ELSE 'herscovitch2002' END, 'artikel', 'Commitment to organizational change: Extension of a three-component model.', '[{"achternaam":"Herscovitch","tussenvoegsel":"","voorletters":"L."},{"achternaam":"Meyer","tussenvoegsel":"","voorletters":"J. P."}]', '', '', 2002, 'en', 'https://doi.org/10.1037/0021-9010.87.3.474', '10.1037/0021-9010.87.3.474', '{"tijdschrift":"Journal of Applied Psychology","jaargang":"87","nummer":"3","paginas":"474–487"}', '["cultuur"]', '[]', 'In drie studies toetsen de auteurs of het driecomponentenmodel van betrokkenheid ook werkt voor de betrokkenheid van medewerkers bij een organisatieverandering. In de eerste studie, onder 224 universiteitsstudenten, ontwikkelden ze schalen voor affectieve, continuïteits- en normatieve betrokkenheid bij verandering. Twee studies onder ziekenhuisverpleegkundigen (N = 157 en N = 108) ondersteunden de validiteit van die schalen verder.', '["Het driecomponentenmodel van betrokkenheid wordt in drie studies toegepast op betrokkenheid bij organisatieverandering.","In studie 1 (224 universiteitsstudenten) zijn nieuwe schalen ontwikkeld voor affectieve, continuïteits- en normatieve betrokkenheid bij verandering.","Studie 2 en 3 onder ziekenhuisverpleegkundigen (N = 157 en 108) ondersteunden de validiteit van deze drie schalen verder."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'herscovitch-meyer-2002-commitment-verandering')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'herscovitch2002st');
