SELECT 'start', 'hom-lee-shaw-hausknecht-2017-honderd-jaar-verloop', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'hom2017') THEN 'hom2017st' ELSE 'hom2017' END, 'artikel', 'One hundred years of employee turnover theory and research.', '[{"achternaam":"Hom","tussenvoegsel":"","voorletters":"P. W."},{"achternaam":"Lee","tussenvoegsel":"","voorletters":"T. W."},{"achternaam":"Shaw","tussenvoegsel":"","voorletters":"J. D."},{"achternaam":"Hausknecht","tussenvoegsel":"","voorletters":"J. P."}]', '', '', 2017, 'en', 'https://doi.org/10.1037/apl0000103', '10.1037/apl0000103', '{"tijdschrift":"Journal of Applied Psychology","jaargang":"102","nummer":"3","paginas":"530–545"}', '["vertrek"]', '[]', 'Overzichtsartikel van de toonaangevende publicaties over personeelsverloop uit de eerste honderd jaar van de Journal of Applied Psychology. De auteurs vullen dit aan met publicaties uit andere bronnen die belangrijke theoretische en methodologische bijdragen leverden. Alleen het begin van de samenvatting kon worden gecontroleerd.', '["Het artikel bespreekt de invloedrijkste publicaties over personeelsverloop uit honderd jaar Journal of Applied Psychology.","De review is uitgebreid met publicaties van buiten het tijdschrift die belangrijke theoretische en methodologische bijdragen leverden."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'hom-lee-shaw-hausknecht-2017-honderd-jaar-verloop')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'hom2017st');
