SELECT 'start', 'jiang-lepak-hu-baer-2012-hrm-systemen', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'jiang2012') THEN 'jiang2012st' ELSE 'jiang2012' END, 'artikel', 'How Does Human Resource Management Influence Organizational Outcomes? A Meta-analytic Investigation of Mediating Mechanisms', '[{"achternaam":"Jiang","tussenvoegsel":"","voorletters":"K."},{"achternaam":"Lepak","tussenvoegsel":"","voorletters":"D. P."},{"achternaam":"Hu","tussenvoegsel":"","voorletters":"J."},{"achternaam":"Baer","tussenvoegsel":"","voorletters":"J. C."}]', '', '', 2012, 'en', 'https://doi.org/10.5465/amj.2011.0088', '10.5465/amj.2011.0088', '{"tijdschrift":"Academy of Management Journal","jaargang":"55","nummer":"6","paginas":"1264–1294"}', '["hr-processen","ontwikkeling","vertrek"]', '[]', 'Meta-analyse op basis van het AMO-model (ability-motivation-opportunity) naar drie soorten HR-praktijken: praktijken die vaardigheden vergroten, praktijken die motivatie vergroten en praktijken die kansen bieden. Onderzocht is hoe deze praktijken samenhangen met human capital en motivatie, en via die weg met vrijwillig verloop, operationele resultaten en financiële resultaten. Vaardigheidspraktijken hangen sterker samen met human capital, motivatie- en kansenpraktijken sterker met motivatie. Alle drie hangen direct en indirect samen met financiële resultaten.', '["HR-systemen zijn ingedeeld in drie dimensies: vaardigheden vergroten, motivatie vergroten en kansen bieden.","Vaardigheidspraktijken hangen sterker samen met human capital, maar zwakker met motivatie dan de andere twee soorten praktijken.","De drie dimensies hangen direct én indirect samen met financiële resultaten: via human capital en motivatie, en vervolgens via vrijwillig verloop en operationele resultaten."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'jiang-lepak-hu-baer-2012-hrm-systemen')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'jiang2012st');
