SELECT 'start', 'judge-piccolo-2004-transformationeel-leiderschap', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'judge2004') THEN 'judge2004st' ELSE 'judge2004' END, 'artikel', 'Transformational and Transactional Leadership: A Meta-Analytic Test of Their Relative Validity.', '[{"achternaam":"Judge","tussenvoegsel":"","voorletters":"T. A."},{"achternaam":"Piccolo","tussenvoegsel":"","voorletters":"R. F."}]', '', '', 2004, 'en', 'https://doi.org/10.1037/0021-9010.89.5.755', '10.1037/0021-9010.89.5.755', '{"tijdschrift":"Journal of Applied Psychology","jaargang":"89","nummer":"5","paginas":"755–768"}', '["leiderschap"]', '[]', 'Meta-analyse over het volledige spectrum van transformationeel, transactioneel en laissez-faire leiderschap, op basis van 626 correlaties uit 87 bronnen. Transformationeel leiderschap hangt over het geheel het sterkst samen met de uitkomstmaten. Daarna volgen belonen volgens afspraak (contingent reward) en, in negatieve richting, laissez-faire leiderschap. Opvallend is dat belonen volgens afspraak voor een aantal uitkomsten sterker samenhangt dan transformationeel leiderschap, en dat beide stijlen onderling sterk samenhangen.', '["Over alle studies samen hangt transformationeel leiderschap met .44 samen met de uitkomstmaten (626 correlaties uit 87 bronnen).","Belonen volgens afspraak (.39) en laissez-faire leiderschap (-.37) volgen daarna als sterkste samenhangen. Management by exception laat geen consistent beeld zien.","Voor meerdere uitkomstmaten hangt belonen volgens afspraak sterker samen dan transformationeel leiderschap.","Transformationeel leiderschap hangt sterk samen met belonen volgens afspraak (.80) en sterk negatief met laissez-faire leiderschap (-.65)."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'judge-piccolo-2004-transformationeel-leiderschap')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'judge2004st');
