SELECT 'start', 'judge-thoresen-bono-patton-2001-tevredenheid-prestatie', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'judge2001') THEN 'judge2001st' ELSE 'judge2001' END, 'artikel', 'The job satisfaction–job performance relationship: A qualitative and quantitative review.', '[{"achternaam":"Judge","tussenvoegsel":"","voorletters":"T. A."},{"achternaam":"Thoresen","tussenvoegsel":"","voorletters":"C. J."},{"achternaam":"Bono","tussenvoegsel":"","voorletters":"J. E."},{"achternaam":"Patton","tussenvoegsel":"","voorletters":"G. K."}]', '', '', 2001, 'en', 'https://doi.org/10.1037/0033-2909.127.3.376', '10.1037/0033-2909.127.3.376', '{"tijdschrift":"Psychological Bulletin","jaargang":"127","nummer":"3","paginas":"376–407"}', '["tevredenheid"]', '[]', 'Kwalitatief en kwantitatief overzicht van het verband tussen arbeidstevredenheid en werkprestatie. Het kwalitatieve deel bespreekt zeven modellen uit eerder onderzoek; geen enkel model is eenduidig bevestigd of weerlegd. Een nieuwe meta-analyse over 312 steekproeven (samen N = 54.417) schat de gemiddelde ware correlatie tussen algemene tevredenheid en prestatie op .30.', '["De nieuwe meta-analyse omvat 312 steekproeven met samen 54.417 deelnemers.","De gemiddelde ware correlatie tussen algemene arbeidstevredenheid en werkprestatie wordt geschat op .30.","Van de zeven besproken modellen over dit verband is er geen eenduidig bevestigd of weerlegd."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'judge-thoresen-bono-patton-2001-tevredenheid-prestatie')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'judge2001st');
