SELECT 'start', 'kammeyer-mueller-wanberg-2003-organisatie-entree', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'kammeyermueller2003') THEN 'kammeyermueller2003st' ELSE 'kammeyermueller2003' END, 'artikel', 'Unwrapping the organizational entry process: Disentangling multiple antecedents and their pathways to adjustment.', '[{"achternaam":"Kammeyer-Mueller","tussenvoegsel":"","voorletters":"J. D."},{"achternaam":"Wanberg","tussenvoegsel":"","voorletters":"C. R."}]', '', '', 2003, 'en', 'https://doi.org/10.1037/0021-9010.88.5.779', '10.1037/0021-9010.88.5.779', '{"tijdschrift":"Journal of Applied Psychology","jaargang":"88","nummer":"5","paginas":"779–794"}', '["onboarding"]', '[]', 'Longitudinale studie met vier meetmomenten onder nieuwkomers in zeven organisaties. De auteurs onderzochten hoe kennis vooraf, een proactieve persoonlijkheid en invloeden vanuit socialisatie samenhangen met de aanpassing van nieuwkomers op korte termijn: taakbeheersing, rolhelderheid, integratie in de werkgroep en kennis van de organisatiepolitiek. Ook keken ze naar uitkomsten op langere termijn. Alleen het begin van de samenvatting kon worden gecontroleerd.', '["De opzet is longitudinaal: vier meetmomenten onder nieuwkomers in zeven organisaties.","Als voorspellers zijn onderzocht: kennis vooraf, proactieve persoonlijkheid en socialisatie-invloeden.","De aanpassing op korte termijn is uitgesplitst in taakbeheersing, rolhelderheid, integratie in de werkgroep en kennis van de organisatiepolitiek."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'kammeyer-mueller-wanberg-2003-organisatie-entree')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'kammeyermueller2003st');
