SELECT 'start', 'karasek-1979-demand-control', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'karasek1979') THEN 'karasek1979st' ELSE 'karasek1979' END, 'artikel', 'Job Demands, Job Decision Latitude, and Mental Strain: Implications for Job Redesign', '[{"achternaam":"Karasek","tussenvoegsel":"","voorletters":"R. A."}]', '', '', 1979, 'en', 'https://doi.org/10.2307/2392498', '10.2307/2392498', '{"tijdschrift":"Administrative Science Quarterly","jaargang":"24","nummer":"2","paginas":"285–308"}', '["werkdruk"]', '[]', 'Klassiek artikel van Karasek over de samenhang tussen taakeisen, beslissingsruimte (regelmogelijkheden) en mentale spanning, met gevolgen voor het herontwerpen van functies. Let op: in deze sessie zijn alleen de bibliografische gegevens (titel, auteur, tijdschrift, jaargang, pagina''s) gecontroleerd; een abstract was niet beschikbaar. Lees het artikel zelf voordat u specifieke bevindingen citeert.', '["Het artikel koppelt taakeisen en beslissingsruimte (regelruimte) aan mentale spanning.","Het artikel trekt daaruit lessen voor het herontwerpen van functies."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'karasek-1979-demand-control')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'karasek1979st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'lakens-2013-effectgroottes', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'lakens2013') THEN 'lakens2013st' ELSE 'lakens2013' END, 'artikel', 'Calculating and reporting effect sizes to facilitate cumulative science: a practical primer for t-tests and ANOVAs', '[{"achternaam":"Lakens","tussenvoegsel":"","voorletters":"D."}]', '', '', 2013, 'en', 'https://doi.org/10.3389/fpsyg.2013.00863', '10.3389/fpsyg.2013.00863', '{"tijdschrift":"Frontiers in Psychology","jaargang":"4","artikelnummer":"863"}', '["statistiek"]', '[]', 'Praktische handleiding om effectgroottes zoals Cohen''s d en eta-kwadraat te berekenen en te rapporteren bij t-toetsen en variantieanalyses. Lakens legt uit dat effectgroottes de praktische betekenis van een resultaat laten zien, en waarschuwt dat de bekende grenswaarden van Cohen arbitrair zijn. Een spreadsheet ondersteunt de berekeningen.', '["Gestandaardiseerde effectgroottes maken de praktische betekenis van een uitkomst zichtbaar, in plaats van alleen de statistische significantie.","De grenswaarden van Cohen voor d (0,2 / 0,5 / 0,8) zijn arbitrair en moeten niet star worden gebruikt; beter is een effect te vergelijken met andere effecten uit de literatuur en de praktische gevolgen uit te leggen.","De grenswaarden voor η² (0,01 / 0,06 / 0,14) zijn bedoeld voor vergelijkingen tussen onbeperkte populaties (zoals mannen tegenover vrouwen) en passen niet goed bij partiële eta-kwadraat in designs met covariaten of herhaalde metingen.","Onderzoekers rapporteren vaak partiële eta-kwadraat omdat SPSS die geeft; het artikel helpt de juiste effectgrootte te kiezen en biedt een spreadsheet."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'lakens-2013-effectgroottes')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'lakens2013st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'leicht-deobald-et-al-2019-algoritmische-hr', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'leichtdeobald2019') THEN 'leichtdeobald2019st' ELSE 'leichtdeobald2019' END, 'artikel', 'The Challenges of Algorithm-Based HR Decision-Making for Personal Integrity', '[{"achternaam":"Leicht-Deobald","tussenvoegsel":"","voorletters":"U."},{"achternaam":"Busch","tussenvoegsel":"","voorletters":"T."},{"achternaam":"Schank","tussenvoegsel":"","voorletters":"C."},{"achternaam":"Weibel","tussenvoegsel":"","voorletters":"A."},{"achternaam":"Schafheitle","tussenvoegsel":"","voorletters":"S."},{"achternaam":"Wildhaber","tussenvoegsel":"","voorletters":"I."},{"achternaam":"Kasper","tussenvoegsel":"","voorletters":"G."}]', '', '', 2019, 'en', 'https://doi.org/10.1007/s10551-019-04204-w', '10.1007/s10551-019-04204-w', '{"tijdschrift":"Journal of Business Ethics","jaargang":"160","nummer":"2","paginas":"377–392"}', '["privacy","hr-analytics"]', '[]', 'Conceptueel artikel over de ethische risico''s van algoritmische HR-besluitvorming waarmee organisaties medewerkers monitoren. De auteurs stellen dat de efficiëntielogica van zulke tools de balans tussen persoonlijke integriteit en compliance kan doen doorslaan naar compliance. Als tegenwicht noemen ze kritische datageletterdheid, ethisch bewustzijn, participatief ontwerp en private regulering.', '["Organisaties gebruiken steeds vaker algoritmische HR-besluitvorming om medewerkers te monitoren; leveranciers presenteren die tools als efficiënt en objectief en zwakken mogelijke vertekening af.","Dit kan de balans tussen de persoonlijke integriteit van medewerkers en compliance verschuiven richting compliance.","Kritische datageletterdheid, ethisch bewustzijn, participatieve ontwerpmethoden en private regulering kunnen helpen deze problemen te ondervangen."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'leicht-deobald-et-al-2019-algoritmische-hr')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'leichtdeobald2019st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'maslach-schaufeli-leiter-2001-burnout', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'maslach2001') THEN 'maslach2001st' ELSE 'maslach2001' END, 'artikel', 'Job Burnout', '[{"achternaam":"Maslach","tussenvoegsel":"","voorletters":"C."},{"achternaam":"Schaufeli","tussenvoegsel":"","voorletters":"W. B."},{"achternaam":"Leiter","tussenvoegsel":"","voorletters":"M. P."}]', '', '', 2001, 'en', 'https://doi.org/10.1146/annurev.psych.52.1.397', '10.1146/annurev.psych.52.1.397', '{"tijdschrift":"Annual Review of Psychology","jaargang":"52","nummer":"1","paginas":"397–422"}', '["werkdruk"]', '[]', 'Overzichtsartikel over burn-out. Burn-out wordt beschreven als een langdurige reactie op chronische emotionele en interpersoonlijke stressoren in het werk, met drie dimensies: uitputting, cynisme en verminderde effectiviteit. Volgens de auteurs heeft 25 jaar onderzoek de complexiteit van het begrip laten zien. (Gebaseerd op het beschikbare, ingekorte abstract.)', '["Burn-out is een langdurige reactie op chronische emotionele en interpersoonlijke stressoren in het werk.","Burn-out wordt gedefinieerd door drie dimensies: uitputting, cynisme en inefficacy (verminderde effectiviteit).","Een kwarteeuw onderzoek heeft laten zien dat het begrip complex is."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'maslach-schaufeli-leiter-2001-burnout')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'maslach2001st');
