SELECT 'start', 'mathisen-2022-psychosociaal-verzuim', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'mathisen2022') THEN 'mathisen2022st' ELSE 'mathisen2022' END, 'artikel', 'Impact of hypothetical improvements in the psychosocial work environment on sickness absence rates: a simulation study', '[{"achternaam":"Mathisen","tussenvoegsel":"","voorletters":"J."},{"achternaam":"Nguyen","tussenvoegsel":"","voorletters":"T.-L."},{"achternaam":"Jensen","tussenvoegsel":"","voorletters":"J. H."},{"achternaam":"Mehta","tussenvoegsel":"","voorletters":"A. J."},{"achternaam":"Rugulies","tussenvoegsel":"","voorletters":"R."},{"achternaam":"Rod","tussenvoegsel":"","voorletters":"N. H."}]', '', '', 2022, 'en', 'https://doi.org/10.1093/eurpub/ckac109', '10.1093/eurpub/ckac109', '{"tijdschrift":"European Journal of Public Health","jaargang":"32","nummer":"5","paginas":"716–722"}', '["verzuim","sociale-veiligheid","werkdruk"]', '[]', 'Longitudinale studie onder 24.990 medewerkers van openbare ziekenhuizen. Met een simulatiemethode (parametrische g-formule) is berekend hoeveel het verzuim zou dalen als 17 psychosociale werkfactoren verbeteren. Alle factoren op het gunstigste niveau, vergeleken met het ongunstigste niveau, ging samen met een 54% lager verzuimcijfer. Minder pesten, minder ervaren stress en meer vaardigheidsbenutting hadden het grootste potentieel. Het gaat om berekende, denkbeeldige scenario''s en niet om een geteste interventie.', '["De studie volgde 24.990 ziekenhuismedewerkers uit de meting van 2014 en onderscheidde kort, middellang en lang verzuim.","Alle 17 psychosociale werkfactoren op het gunstigste niveau (vergeleken met het ongunstigste niveau) ging samen met een 54% lager verzuimcijfer (95%-BI: 48-60%).","Het terugdringen van pesten en ervaren stress en het vergroten van vaardigheidsbenutting hadden het grootste potentieel om verzuim te verlagen.","De verbanden waren vergelijkbaar voor kort, middellang en lang verzuim."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'mathisen-2022-psychosociaal-verzuim')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'mathisen2022st');
