SELECT 'start', 'matthews-harel-aseltine-2017-disclosure-control', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'matthews2017') THEN 'matthews2017st' ELSE 'matthews2017' END, 'artikel', 'A Review of Statistical Disclosure Control Techniques Employed by Web-Based Data Query Systems', '[{"achternaam":"Matthews","tussenvoegsel":"","voorletters":"G. J."},{"achternaam":"Harel","tussenvoegsel":"","voorletters":"O."},{"achternaam":"Aseltine","tussenvoegsel":"","voorletters":"R. H."}]', '', '', 2017, 'en', 'https://doi.org/10.1097/PHH.0000000000000473', '10.1097/PHH.0000000000000473', '{"tijdschrift":"Journal of Public Health Management and Practice","jaargang":"23","nummer":"4","paginas":"e1–e4"}', '["privacy","hr-analytics"]', '[]', 'Systematische review van de technieken waarmee webgebaseerde querysystemen voor volksgezondheidsdata (opgenomen in de lijst van de Amerikaanse vereniging NAPHSIS) proberen te voorkomen dat geaggregeerde cijfers herleidbaar zijn (statistical disclosure control). Veel systemen pasten geen beveiliging toe, en waar dat wel gebeurde was het vaak inconsistent of onvoldoende. In een deel van de systemen waren onderdrukte waarden alsnog te achterhalen.', '["De auteurs hebben systematisch onderzocht hoe webgebaseerde querysystemen geaggregeerde data publiceren en welke disclosure-control-technieken ze toepassen.","Van de 35 onderzochte systemen paste meer dan de helft (18) geen onderdrukking toe, en in 9 systemen waren onderdrukte waarden te achterhalen.","Veel systemen gebruikten helemaal geen disclosure control; de meeste systemen die het wel deden, pasten het inconsistent of ontoereikend toe."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'matthews-harel-aseltine-2017-disclosure-control')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'matthews2017st');
