SELECT 'start', 'meyer-allen-1991-driecomponenten-commitment', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'meyer1991') THEN 'meyer1991st' ELSE 'meyer1991' END, 'artikel', 'A three-component conceptualization of organizational commitment', '[{"achternaam":"Meyer","tussenvoegsel":"","voorletters":"J. P."},{"achternaam":"Allen","tussenvoegsel":"","voorletters":"N. J."}]', '', '', 1991, 'en', 'https://doi.org/10.1016/1053-4822(91)90011-Z', '10.1016/1053-4822(91)90011-Z', '{"tijdschrift":"Human Resource Management Review","jaargang":"1","nummer":"1","paginas":"61–89"}', '["vertrek","tevredenheid"]', '[]', 'Conceptueel artikel dat organisatiebetrokkenheid (commitment) beschrijft als een psychologische toestand met minstens drie te onderscheiden onderdelen. Affectieve betrokkenheid gaat over willen blijven, continuïteitsbetrokkenheid over moeten blijven en normatieve betrokkenheid over je verplicht voelen te blijven.', '["Organisatiebetrokkenheid is volgens de auteurs een psychologische toestand met minstens drie te onderscheiden componenten.","Die componenten zijn verlangen (affectief), noodzaak (continuïteit) en verplichting (normatief) om bij de organisatie te blijven."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'meyer-allen-1991-driecomponenten-commitment')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'meyer1991st');
