SELECT 'start', 'michiels-2025-werkdruk-vertrek', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'michiels2025') THEN 'michiels2025st' ELSE 'michiels2025' END, 'rapport', 'In hoeverre draagt een hoge werkdruk bij aan het vertrek van werknemers?', '[{"achternaam":"Michiels","tussenvoegsel":"","voorletters":"J."}]', 'Centraal Bureau voor de Statistiek', 'CBS', 2025, 'nl', 'https://www.cbs.nl/nl-nl/longread/statistische-trends/2025/in-hoeverre-draagt-een-hoge-werkdruk-bij-aan-het-vertrek-van-werknemers-', '', '{}', '["werkdruk","vertrek","tevredenheid"]', '[]', 'Het CBS onderzocht of werknemers met een hoge werkdruk vaker vertrekken. Daarvoor zijn NEA-antwoorden uit 2021 gekoppeld aan gegevens over banen en uitkeringen een jaar later. Werknemers met een hoge werkdruk stappen vaker over naar een andere baan. Dat verband loopt vooral via een lagere werktevredenheid en meer burn-outklachten. Met uitstroom naar een uitkering of pensioen vond het CBS binnen een jaar geen significant verband.', '["Een hogere werkdruk hangt samen met vaker een nieuwe baan beginnen, als werknemer of als zelfstandige.","Van de werknemers met hoge werkdruk (stressvol werk) in 2021 had 16,2 procent een jaar later een andere baan als belangrijkste inkomensbron; bij de andere groepen was dat 9,8 tot 12,5 procent.","Het verband loopt voor een belangrijk deel via andere factoren, van belangrijk naar minder belangrijk: werktevredenheid, burn-outklachten en ervaren gezondheid. Lagere werktevredenheid en burn-outklachten maken een overstap waarschijnlijker, een slechtere ervaren gezondheid juist minder.","Met uitstroom naar een uitkering, pensioen of overige uitstroom vond het CBS geen significante samenhang. Mogelijk is één jaar daarvoor te kort."]', 'hoog', 'Officiële statistiek van het CBS.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'michiels-2025-werkdruk-vertrek')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'michiels2025st');
