SELECT 'start', 'nielsen-matthiesen-einarsen-2010-prevalentie-pesten', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'nielsen2010') THEN 'nielsen2010st' ELSE 'nielsen2010' END, 'artikel', 'The impact of methodological moderators on prevalence rates of workplace bullying. A meta-analysis', '[{"achternaam":"Nielsen","tussenvoegsel":"","voorletters":"M. B."},{"achternaam":"Matthiesen","tussenvoegsel":"","voorletters":"S. B."},{"achternaam":"Einarsen","tussenvoegsel":"","voorletters":"S."}]', '', '', 2010, 'en', 'https://doi.org/10.1348/096317909X481256', '10.1348/096317909X481256', '{"tijdschrift":"Journal of Occupational and Organizational Psychology","jaargang":"83","nummer":"4","paginas":"955–979"}', '["sociale-veiligheid","methode"]', '[]', 'Meta-analyse over de vraag hoe meetmethode en steekproef het gevonden percentage pesten op het werk beïnvloeden. De auteurs bundelden 102 schattingen uit 86 onafhankelijke steekproeven (N = 130.973); gemiddeld kwamen de onafhankelijke steekproeven uit op 14,6%. Het percentage hangt wel af van de meetmethode: van 11,3% als mensen zelf aangeven of ze gepest worden en daarbij een definitie van pesten krijgen, tot 18,1% als ze dat zonder definitie aangeven. Cijfers uit verschillende studies kun je daarom niet zomaar met elkaar vergelijken.', '["Gemiddeld kwamen de 86 onafhankelijke steekproeven in deze meta-analyse (2010) uit op een pestpercentage van 14,6%.","De meetmethode maakt uit: 11,3% als mensen zelf aangeven of ze gepest worden en een definitie van pesten krijgen, 14,8% bij een lijst met pestgedragingen en 18,1% als mensen zelf aangeven of ze gepest worden zonder definitie.","Tussen studies met en zonder willekeurige steekproef zat een verschil van 8,7 procentpunt.","Ook geografische factoren spelen mee; vergelijk pestcijfers uit verschillende studies alleen als je rekening houdt met deze verschillen in methode en regio."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'nielsen-matthiesen-einarsen-2010-prevalentie-pesten')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'nielsen2010st');
