SELECT 'start', 'nla-2026-werkdruk', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'nederlandse2026b') THEN 'nederlandse2026bst' ELSE 'nederlandse2026b' END, 'website', 'Werkdruk', '[]', 'Nederlandse Arbeidsinspectie', '', 2026, 'nl', 'https://www.nlarbeidsinspectie.nl/onderwerpen/arbeidsomstandighedenwet/werkdruk-en-ongewenst-gedrag/werkdruk', '', '{"geraadpleegd":"2026-11-27"}', '["werkdruk","wetgeving","verzuim"]', '[]', 'De Arbeidsinspectie legt uit dat werkdruk ontstaat als de eisen van het werk niet in balans zijn met wat een werknemer aankan. Werkgevers moeten volgens de Arbowet beleid hebben tegen langdurig hoge werkdruk, gebaseerd op de RI&E. Blijkt werkdruk een reëel risico, dan volgen vaste stappen: verdiepend onderzoek, analyse, maatregelen kiezen en vastleggen in een plan van aanpak, uitvoeren en evalueren. Doet een werkgever dit niet, dan kan de inspectie maatregelen nemen en uiteindelijk hoge boetes geven.', '["Werkdruk is er als de eisen van het werk niet in balans zijn met de belastbaarheid van de werknemer.","Blijkt werkdruk een reëel risico, dan is een verdiepend onderzoek naar werkdruk de eerste stap.","Oorzaken zijn onder meer te weinig tijd, te weinig inspraak en onduidelijke verwachtingen.","Zonder beleid tegen te hoge werkdruk kan de Nederlandse Arbeidsinspectie maatregelen nemen."]', 'redelijk', 'Informatie van een overheidsorganisatie.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'nla-2026-werkdruk')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'nederlandse2026bst');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'nla-2026-werkdruk-ongewenst-gedrag', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'nederlandse2026') THEN 'nederlandse2026st' ELSE 'nederlandse2026' END, 'website', 'Werkdruk en ongewenst gedrag', '[]', 'Nederlandse Arbeidsinspectie', '', 2026, 'nl', 'https://www.nlarbeidsinspectie.nl/onderwerpen/arbeidsomstandighedenwet/werkdruk-en-ongewenst-gedrag', '', '{"geraadpleegd":"2026-11-27"}', '["sociale-veiligheid","werkdruk","wetgeving"]', '[]', 'Deze pagina beschrijft psychosociale arbeidsbelasting (PSA): werkstress door factoren als agressie en geweld, discriminatie, pesten, seksuele intimidatie en werkdruk. PSA kan leiden tot verzuim, langdurige uitval en mogelijk arbeidsongeschiktheid. De werkgever moet volgens de Arbowet beleid tegen PSA hebben, gebaseerd op de RI&E, met een plan van aanpak en evaluatie van de maatregelen. De pagina noemt voorbeelden van maatregelen en legt de taken van de vertrouwenspersoon uit.', '["Werkgevers moeten volgens de Arbowet beleid vaststellen om PSA tegen te gaan.","Dat beleid bouw je op de RI&E, met een plan van aanpak en evaluatie van de maatregelen.","Voorbeelden van maatregelen zijn een vertrouwenspersoon, voorlichting, verdiepend werkdrukonderzoek en een gedragscode met klachtenprocedure.","De vertrouwenspersoon heeft geheimhoudingsplicht en geeft geen inhoud van gesprekken door aan de werkgever."]', 'redelijk', 'Informatie van een overheidsorganisatie.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'nla-2026-werkdruk-ongewenst-gedrag')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'nederlandse2026st');
