SELECT 'start', 'norman-2010-likert-parametrisch', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'norman2010') THEN 'norman2010st' ELSE 'norman2010' END, 'artikel', 'Likert scales, levels of measurement and the “laws” of statistics', '[{"achternaam":"Norman","tussenvoegsel":"","voorletters":"G."}]', '', '', 2010, 'en', 'https://doi.org/10.1007/s10459-010-9222-y', '10.1007/s10459-010-9222-y', '{"tijdschrift":"Advances in Health Sciences Education","jaargang":"15","nummer":"5","paginas":"625–632"}', '["statistiek"]', '[]', 'Norman bespreekt de veelgehoorde kritiek dat parametrische methoden niet mogen bij kleine steekproeven, niet-normaal verdeelde data of data van een bepaald meetniveau, zoals Likert-schalen. Hij laat zien dat onderzoek sinds de jaren 1930 consequent wijst op de robuustheid van parametrische statistiek voor zulke schendingen. Zijn conclusie is dat de kritiek ongegrond is en dat parametrische methoden gewoon gebruikt kunnen worden.', '["Parametrische methoden zoals variantieanalyse, regressie en correlatie krijgen vaak kritiek omdat de steekproef te klein zou zijn, de data niet normaal verdeeld zouden zijn, of vanwege het soort data; het artikel gaat daarbij over Likert-schalen en meetniveaus.","Studies sinds de jaren 1930 laten consequent zien dat parametrische statistiek robuust is voor schendingen van deze aannames; volgens de auteur is de kritiek daarom ongegrond."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'norman-2010-likert-parametrisch')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'norman2010st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'odonovan-mcauliffe-2020-psych-safety-interventions', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'odonovan2020') THEN 'odonovan2020st' ELSE 'odonovan2020' END, 'artikel', 'A systematic review exploring the content and outcomes of interventions to improve psychological safety, speaking up and voice behaviour', '[{"achternaam":"O''Donovan","tussenvoegsel":"","voorletters":"R."},{"achternaam":"McAuliffe","tussenvoegsel":"","voorletters":"E."}]', '', '', 2020, 'en', 'https://doi.org/10.1186/s12913-020-4931-2', '10.1186/s12913-020-4931-2', '{"tijdschrift":"BMC Health Services Research","jaargang":"20","nummer":"1","artikelnummer":"101"}', '["sociale-veiligheid","leiderschap"]', '[]', 'Systematische review van interventies die psychologische veiligheid, aanspreken (speaking up) en voice-gedrag in de zorg willen verbeteren. Veertien interventies in vijf categorieën werden beoordeeld, van trainingen met simulatie en casuïstiek tot facilitatie en actieonderzoek. De effecten waren wisselend; de auteurs pleiten voor langdurige, meervoudige interventies op team- en organisatieniveau met zichtbare steun van leidinggevenden.', '["Veertien interventies werden beoordeeld, verdeeld over vijf categorieën.","De effectiviteit van de interventies was wisselend.","Er zijn longitudinale en meervoudige (multifaceted) interventies nodig.","Aanbevolen: zowel team- als organisatieniveau aanpakken, zorgen voor zichtbare steun van leidinggevenden en werken binnen en tussen disciplines."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'odonovan-mcauliffe-2020-psych-safety-interventions')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'odonovan2020st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'oreg-vakola-armenakis-2011-reacties-verandering', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'oreg2011') THEN 'oreg2011st' ELSE 'oreg2011' END, 'artikel', 'Change Recipients'' Reactions to Organizational Change: A 60-Year Review of Quantitative Studies', '[{"achternaam":"Oreg","tussenvoegsel":"","voorletters":"S."},{"achternaam":"Vakola","tussenvoegsel":"","voorletters":"M."},{"achternaam":"Armenakis","tussenvoegsel":"","voorletters":"A."}]', '', '', 2011, 'en', 'https://doi.org/10.1177/0021886310396550', '10.1177/0021886310396550', '{"tijdschrift":"The Journal of Applied Behavioral Science","jaargang":"47","nummer":"4","paginas":"461–524"}', '["cultuur"]', '[]', 'Review van kwantitatief onderzoek naar hoe medewerkers reageren op organisatieveranderingen. Van de studies uit 1948-2007 voldeden er 79 aan de criteria. De auteurs leiden er een model uit af waarin reacties driedimensionale attitudes zijn. Voorspellers liggen vóór de verandering (kenmerken van medewerkers, interne context) en in de verandering zelf (veranderproces, ervaren voor- of nadeel, inhoud). Het model onderscheidt ook werkgerelateerde en persoonlijke gevolgen.', '["De review omvat 79 kwantitatieve studies, gepubliceerd tussen 1948 en 2007.","Reacties op verandering worden opgevat als attitudes met drie dimensies.","Voorspellers liggen vóór de verandering (kenmerken van medewerkers, interne context) en in de verandering zelf (proces, ervaren voor- of nadeel, inhoud).","Gevolgen van verandering zijn zowel werkgerelateerd als persoonlijk."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'oreg-vakola-armenakis-2011-reacties-verandering')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'oreg2011st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'podsakoff-mackenzie-lee-podsakoff-2003-common-method-bias', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'podsakoff2003') THEN 'podsakoff2003st' ELSE 'podsakoff2003' END, 'artikel', 'Common method biases in behavioral research: A critical review of the literature and recommended remedies.', '[{"achternaam":"Podsakoff","tussenvoegsel":"","voorletters":"P. M."},{"achternaam":"MacKenzie","tussenvoegsel":"","voorletters":"S. B."},{"achternaam":"Lee","tussenvoegsel":"","voorletters":"J.-Y."},{"achternaam":"Podsakoff","tussenvoegsel":"","voorletters":"N. P."}]', '', '', 2003, 'en', 'https://doi.org/10.1037/0021-9010.88.5.879', '10.1037/0021-9010.88.5.879', '{"tijdschrift":"Journal of Applied Psychology","jaargang":"88","nummer":"5","paginas":"879–903"}', '["methode"]', '[]', 'Kritisch literatuuroverzicht over methodevertekening (common method bias) in gedragswetenschappelijk onderzoek. De auteurs gaan na in welke mate zulke vertekening onderzoeksresultaten beïnvloedt, welke bronnen er zijn en via welke cognitieve processen antwoorden op meetinstrumenten vertekend raken. Het artikel sluit af met aanbevolen remedies.', '["Methodevertekening is een lang bekend probleem in gedragswetenschappelijk onderzoek, maar er ontbrak een volledig overzicht van de bronnen en van manieren om ze te beheersen.","Het artikel onderzoekt hoe sterk methodevertekening resultaten beïnvloedt, welke bronnen er zijn en via welke cognitieve processen antwoorden op vragen worden beïnvloed.","Het artikel geeft aanbevolen remedies tegen methodevertekening."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'podsakoff-mackenzie-lee-podsakoff-2003-common-method-bias')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'podsakoff2003st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'rhoades-eisenberger-2002-ervaren-organisatiesteun', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'rhoades2002') THEN 'rhoades2002st' ELSE 'rhoades2002' END, 'artikel', 'Perceived organizational support: A review of the literature.', '[{"achternaam":"Rhoades","tussenvoegsel":"","voorletters":"L."},{"achternaam":"Eisenberger","tussenvoegsel":"","voorletters":"R."}]', '', '', 2002, 'en', 'https://doi.org/10.1037/0021-9010.87.4.698', '10.1037/0021-9010.87.4.698', '{"tijdschrift":"Journal of Applied Psychology","jaargang":"87","nummer":"4","paginas":"698–714"}', '["hr-processen","tevredenheid"]', '[]', 'Review van meer dan 70 studies over ervaren organisatiesteun (perceived organizational support, POS): het algemene beeld van medewerkers dat hun organisatie hun bijdrage waardeert en om hun welzijn geeft. Uit de meta-analyse blijkt dat drie soorten gunstige behandeling samenhangen met POS: eerlijkheid, steun van de leidinggevende, en beloningen en gunstige werkomstandigheden. POS hangt op zijn beurt samen met uitkomsten die gunstig zijn voor medewerkers.', '["Het review omvat meer dan 70 studies over het algemene beeld van medewerkers dat de organisatie hun bijdrage waardeert en om hun welzijn geeft.","Drie soorten gunstige behandeling hangen samen met POS: eerlijkheid, steun van de leidinggevende, en beloningen en gunstige werkomstandigheden.","POS hangt op zijn beurt samen met uitkomsten die gunstig zijn voor medewerkers."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'rhoades-eisenberger-2002-ervaren-organisatiesteun')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'rhoades2002st');
