SELECT 'start', 'rumbold-pierscionek-2017-avg-onderzoek', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'rumbold2017') THEN 'rumbold2017st' ELSE 'rumbold2017' END, 'artikel', 'The Effect of the General Data Protection Regulation on Medical Research', '[{"achternaam":"Rumbold","tussenvoegsel":"","voorletters":"J. M. M."},{"achternaam":"Pierscionek","tussenvoegsel":"","voorletters":"B."}]', '', '', 2017, 'en', 'https://doi.org/10.2196/jmir.7108', '10.2196/jmir.7108', '{"tijdschrift":"Journal of Medical Internet Research","jaargang":"19","nummer":"2","artikelnummer":"e47"}', '["wetgeving","privacy"]', '[]', 'Ethisch-juridische analyse van de gevolgen van de AVG voor onderzoek met persoonsgegevens, vooral medisch onderzoek. De auteurs benadrukken dat de AVG duidelijker maakt dat gepseudonimiseerde gegevens persoonsgegevens zijn, al is dat niet helemaal opgelost. Ze wijzen op het risico dat gegevens weer te koppelen zijn als de codesleutel uitlekt.', '["De AVG maakt duidelijker dat gepseudonimiseerde gegevens als persoonsgegevens gelden; overweging 26 bevestigt dat.","Als de codesleutel wordt gehackt, kunnen alle gegevens weer aan personen worden gekoppeld.","De AVG beoogt consistente bescherming van betrokkenen in de hele EU."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'rumbold-pierscionek-2017-avg-onderzoek')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'rumbold2017st');
