SELECT 'start', 'schaufeli-bakker-2004-burnout-bevlogenheid', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'schaufeli2004') THEN 'schaufeli2004st' ELSE 'schaufeli2004' END, 'artikel', 'Job demands, job resources, and their relationship with burnout and engagement: a multi-sample study', '[{"achternaam":"Schaufeli","tussenvoegsel":"","voorletters":"W. B."},{"achternaam":"Bakker","tussenvoegsel":"","voorletters":"A. B."}]', '', '', 2004, 'en', 'https://doi.org/10.1002/job.248', '10.1002/job.248', '{"tijdschrift":"Journal of Organizational Behavior","jaargang":"25","nummer":"3","paginas":"293–315"}', '["werkdruk","tevredenheid","vertrek"]', '[]', 'Studie naar burn-out en bevlogenheid (engagement) als tegenpolen met verschillende mogelijke oorzaken en gevolgen, in vier onafhankelijke steekproeven uit verschillende beroepsgroepen (samen N = 1698). Burn-out hangt vooral samen met taakeisen en ook met een gebrek aan hulpbronnen; bevlogenheid alleen met beschikbare hulpbronnen. Burn-out hangt samen met gezondheidsklachten en vertrekintentie, bevlogenheid alleen met vertrekintentie. Daarom zijn volgens de auteurs verschillende interventies nodig om burn-out te verminderen of bevlogenheid te vergroten.', '["Burn-out en bevlogenheid hangen negatief samen en delen 10 tot 25 procent van hun variantie; ze overlappen dus maar gedeeltelijk.","Burn-out wordt vooral voorspeld door taakeisen en ook door gebrek aan hulpbronnen; bevlogenheid alleen door beschikbare hulpbronnen.","Burn-out hangt samen met gezondheidsklachten en vertrekintentie; bevlogenheid alleen met vertrekintentie.","Burn-out verminderen en bevlogenheid vergroten vragen om verschillende interventies."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'schaufeli-bakker-2004-burnout-bevlogenheid')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'schaufeli2004st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'schaufeli-bakker-salanova-2006-uwes9', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'schaufeli2006') THEN 'schaufeli2006st' ELSE 'schaufeli2006' END, 'artikel', 'The Measurement of Work Engagement With a Short Questionnaire: A Cross-National Study', '[{"achternaam":"Schaufeli","tussenvoegsel":"","voorletters":"W. B."},{"achternaam":"Bakker","tussenvoegsel":"","voorletters":"A. B."},{"achternaam":"Salanova","tussenvoegsel":"","voorletters":"M."}]', '', '', 2006, 'en', 'https://doi.org/10.1177/0013164405282471', '10.1177/0013164405282471', '{"tijdschrift":"Educational and Psychological Measurement","jaargang":"66","nummer":"4","paginas":"701–716"}', '["tevredenheid","methode"]', '[]', 'Het artikel beschrijft de ontwikkeling van de UWES-9, een verkorte vragenlijst voor bevlogenheid. Bevlogenheid is een positieve werkgerelateerde toestand met vitaliteit, toewijding en absorptie. Met gegevens uit 10 landen (N = 14.521) is de oorspronkelijke versie met 17 items ingekort tot 9 items, met goede interne consistentie en test-hertestbetrouwbaarheid. Volgens de auteurs kan bevlogenheid worden gezien als de positieve tegenpool van burn-out.', '["Bevlogenheid is een positieve werkgerelateerde toestand van vervulling, gekenmerkt door vitaliteit (vigor), toewijding en absorptie.","Op basis van data uit 10 landen (N = 14.521) is de UWES ingekort van 17 naar 9 items (UWES-9).","De drie schaalscores hebben een goede interne consistentie en test-hertestbetrouwbaarheid.","Bevlogenheid kan worden opgevat als de positieve tegenpool van burn-out."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'schaufeli-bakker-salanova-2006-uwes9')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'schaufeli2006st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'schaufeli-desart-dewitte-2020-bat', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'schaufeli2020') THEN 'schaufeli2020st' ELSE 'schaufeli2020' END, 'artikel', 'Burnout Assessment Tool (BAT)—Development, Validity, and Reliability', '[{"achternaam":"Schaufeli","tussenvoegsel":"","voorletters":"W. B."},{"achternaam":"Desart","tussenvoegsel":"","voorletters":"S."},{"achternaam":"Witte","tussenvoegsel":"de","voorletters":"H."}]', '', '', 2020, 'en', 'https://doi.org/10.3390/ijerph17249495', '10.3390/ijerph17249495', '{"tijdschrift":"International Journal of Environmental Research and Public Health","jaargang":"17","nummer":"24","paginas":"9495"}', '["werkdruk","methode"]', '[]', 'Het artikel introduceert een nieuwe definitie van burn-out en de Burnout Assessment Tool (BAT). Na interviews met 49 praktijkdeskundigen kwamen vier kerndimensies (uitputting, mentale distantie, emotionele en cognitieve beperkingen) en drie secundaire dimensies naar voren. In een representatieve steekproef van 1500 Vlaamse werknemers bleken de kerndimensies goed samen te vatten in één algemene burn-outfactor, met voldoende betrouwbaarheid en onderscheid van bevlogenheid en workaholisme.', '["Burn-out wordt gedefinieerd als een werkgerelateerde uitputtingstoestand met extreme vermoeidheid, verminderd vermogen om cognitieve en emotionele processen te reguleren, en mentale distantie.","De BAT kent vier kerndimensies (uitputting, mentale distantie, emotionele en cognitieve beperking) en secundaire klachten (sombere stemming, psychische en psychosomatische klachten).","In een representatieve steekproef van 1500 Vlaamse werknemers vormden de kerndimensies samen één algemene burn-outfactor; de BAT en de subschalen zijn voldoende betrouwbaar.","De BAT is te onderscheiden van andere welzijnsbegrippen zoals bevlogenheid en workaholisme."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'schaufeli-desart-dewitte-2020-bat')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'schaufeli2020st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'ser-2022-hybride-werken', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'ser2022') THEN 'ser2022st' ELSE 'ser2022' END, 'rapport', 'Hybride werken', '[]', 'Sociaal-Economische Raad', 'SER', 2022, 'nl', 'https://www.ser.nl/nl/Publicaties/toekomst-hybride-werken', '', '{"rapportnummer":"22/03"}', '["hybride","arbeidsvoorwaarden","wetgeving"]', '[]', 'In dit advies over hybride werken pleit de SER voor voldoende zeggenschap voor werknemers en voldoende ruimte voor maatwerk voor werkgevers, met afspraken die zij samen maken. De SER wil de wetten ''Werken waar je wilt'' en ''Flexibel werken'' bijstellen, met een toets op redelijkheid en billijkheid. Ook moet hybride werken een vast onderdeel van het arbobeleid worden, om fysieke en mentale klachten te voorkomen. Daarbij moet rekening worden gehouden met werkenden die niet hybride kunnen of willen werken.', '["Werknemers moeten voldoende zeggenschap krijgen en werkgevers voldoende ruimte voor maatwerk; overleg tussen beiden is belangrijk.","De SER adviseert om bepaalde verzoeken om op een andere plek te werken (zoals thuis) te toetsen aan redelijkheid en billijkheid, in plaats van aan zwaarwegende bedrijfsbelangen.","Hybride werken hoort in het gewone arbobeleid, bijvoorbeeld in de RI&E, om fysieke en mentale klachten te voorkomen.","Bij beleid voor hybride werken moet ook rekening worden gehouden met de grote groep werkenden die niet hybride kan of wil werken."]', 'redelijk', 'Informatie van een overheidsorganisatie.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'ser-2022-hybride-werken')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'ser2022st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'ser-2026-handreiking-psa', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'ser2026') THEN 'ser2026st' ELSE 'ser2026' END, 'rapport', 'Handreiking psychosociale arbeidsbelasting (PSA)', '[]', 'Sociaal-Economische Raad', 'SER', 2026, 'nl', 'https://www.ser.nl/nl/publicaties/psychosociale-arbeidsbelasting', '', '{}', '["werkdruk","sociale-veiligheid","wetgeving","verzuim"]', '[]', 'In deze handreiking legt de SER uit wat psychosociale arbeidsbelasting (PSA) is en wat de Arbowet van werkgevers vraagt. Volgens de wet gaat het in ieder geval om agressie of geweld, discriminatie, pesten, seksuele intimidatie en werkdruk. De handreiking geeft landelijke cijfers en twee stappenplannen: één voor brancheorganisaties (arbocatalogus) en één in elf stappen voor organisaties zelf, van scope en RI&E tot evaluatie en borging. Werknemers moeten expliciet gevraagd worden naar hun ervaringen met ongewenste omgangsvormen, bijvoorbeeld met een vragenlijst of interviews, en de OR heeft instemmingsrecht op de manier waarop de RI&E wordt uitgevoerd en op het plan van aanpak.', '["De Arbowet (artikel 1) omschrijft PSA als blootstelling aan factoren in het werk die stress veroorzaken, met in ieder geval vijf genoemde stressoren.","In 2023 verzuimden werknemers in Nederland in totaal 14,3 miljoen dagen als gevolg van PSA, volgens de cijfers in hoofdstuk 2 van de handreiking.","Werknemers moeten expliciet worden geraadpleegd over ongewenste omgangsvormen, bijvoorbeeld via een vragenlijst en/of interviews.","De OR heeft instemmingsrecht op de wijze waarop de RI&E wordt uitgevoerd en op het plan van aanpak."]', 'redelijk', 'Informatie van een overheidsorganisatie.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'ser-2026-handreiking-psa')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'ser2026st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'ser-zj-medezeggenschap-arbo', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'serzdb') THEN 'serzdbst' ELSE 'serzdb' END, 'website', 'Medezeggenschap en arbeidsomstandigheden', '[]', 'Sociaal-Economische Raad', 'SER', NULL, 'nl', 'https://www.ser.nl/nl/thema/medezeggenschap/belangrijke-themas/arbeidsomstandigheden', '', '{"geraadpleegd":"2026-11-27"}', '["wetgeving","werkdruk","hr-processen"]', '[]', 'De SER legt uit welke rechten de ondernemingsraad (OR) en de personeelsvertegenwoordiging (pvt) hebben bij het arbobeleid. Volgens de WOR heeft de OR instemmingsrecht bij regelingen over arbeidsomstandigheden, ziekteverzuim en re-integratie, voor zover de werkgever nog keuzeruimte heeft. Dat geldt onder meer voor de inhoud en aanpak van de RI&E en de keuze van de arbodienst. Verder heeft de OR adviesrecht, een stimulerende taak en het recht om met de inspecteur van de Arbeidsinspectie mee te lopen.', '["Het instemmingsrecht van de OR bij arbo, verzuim en re-integratie staat in artikel 27 lid 1 onder d WOR.","Dat instemmingsrecht geldt onder meer voor de inhoud en aanpak van de RI&E.","Het beperken van psychosociale arbeidsbelasting is een belangrijk onderdeel van goed arbobeleid.","De OR of pvt mag met de inspecteur meelopen en vertrouwelijk met de inspecteur overleggen."]', 'redelijk', 'Informatie van een overheidsorganisatie.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'ser-zj-medezeggenschap-arbo')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'serzdbst');
