SELECT 'start', 'ser-zj-medezeggenschap-privacy', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'serzd') THEN 'serzdst' ELSE 'serzd' END, 'website', 'Medezeggenschap bij privacy van medewerkers', '[]', 'Sociaal-Economische Raad', 'SER', NULL, 'nl', 'https://www.ser.nl/nl/thema/medezeggenschap/belangrijke-themas/privacy', '', '{"geraadpleegd":"2026-11-27"}', '["privacy","wetgeving","hr-analytics"]', '[]', 'De SER legt uit dat de bestuurder volgens de WOR instemming van de OR nodig heeft voor regelingen waarbij persoonsgegevens van werknemers worden verwerkt. Ook voorzieningen die aanwezigheid, gedrag of prestaties volgen, zoals verzuimregistratie of camera''s, vragen OR-instemming. Een personeelsvertegenwoordiging heeft geen instemmingsrecht, maar mag wel informatie vragen. Bij nieuwe algoritmes of AI-tools met persoonsgegevens moeten de privacyrisico''s vooraf in kaart zijn, ook bij een pilot.', '["Regelingen waarbij persoonsgegevens van werknemers worden verwerkt, vragen instemming van de OR.","Voorbeelden die de SER noemt zijn personeelsdossiers, verzuimregistratie en camera''s op de werkplek.","Ook bij een pilot of proef met een algoritme of AI-tool moeten de privacyrisico''s vooraf in kaart zijn gebracht."]', 'redelijk', 'Informatie van een overheidsorganisatie.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'ser-zj-medezeggenschap-privacy')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'serzdst');
