SELECT 'start', 'shore-2011-inclusie-diversiteit-werkgroepen', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'shore2011') THEN 'shore2011st' ELSE 'shore2011' END, 'artikel', 'Inclusion and Diversity in Work Groups: A Review and Model for Future Research', '[{"achternaam":"Shore","tussenvoegsel":"","voorletters":"L. M."},{"achternaam":"Randel","tussenvoegsel":"","voorletters":"A. E."},{"achternaam":"Chung","tussenvoegsel":"","voorletters":"B. G."},{"achternaam":"Dean","tussenvoegsel":"","voorletters":"M. A."},{"achternaam":"Holcombe Ehrhart","tussenvoegsel":"","voorletters":"K."},{"achternaam":"Singh","tussenvoegsel":"","voorletters":"G."}]', '', '', 2011, 'en', 'https://doi.org/10.1177/0149206310385943', '10.1177/0149206310385943', '{"tijdschrift":"Journal of Management","jaargang":"37","nummer":"4","paginas":"1262–1289"}', '["sociale-veiligheid"]', '[]', 'Review en model over inclusie in werkgroepen. Met de optimal distinctiveness theory van Brewer definiëren de auteurs inclusie als het vervuld worden van twee behoeften tegelijk: erbij horen en uniek mogen zijn. Met dat kader bespreken ze de literatuur over diversiteit en inclusie. Ze stellen ook mogelijke contextfactoren en uitkomsten van inclusie voor als leidraad voor verder onderzoek.', '["Inclusie in de werkgroep betekent dat zowel de behoefte om erbij te horen als de behoefte om uniek te zijn wordt vervuld.","De auteurs stellen mogelijke contextfactoren en uitkomsten van inclusie voor, als leidraad voor verder onderzoek."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'shore-2011-inclusie-diversiteit-werkgroepen')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'shore2011st');
