SELECT 'start', 'sijtsma-2009-alpha', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'sijtsma2009') THEN 'sijtsma2009st' ELSE 'sijtsma2009' END, 'artikel', 'On the Use, the Misuse, and the Very Limited Usefulness of Cronbach''s Alpha', '[{"achternaam":"Sijtsma","tussenvoegsel":"","voorletters":"K."}]', '', '', 2009, 'en', 'https://doi.org/10.1007/s11336-008-9101-0', '10.1007/s11336-008-9101-0', '{"tijdschrift":"Psychometrika","jaargang":"74","nummer":"1","paginas":"107–120"}', '["statistiek"]', '[]', 'Discussieartikel van psychometricus Klaas Sijtsma over de beperkingen van Cronbach''s alpha. Hij stelt dat alpha zowel als betrouwbaarheidsschatting als als maat voor interne consistentie grote problemen heeft. Alpha zegt volgens hem niets over de interne structuur van een test.', '["Zowel het gebruik van alpha als betrouwbaarheidsschatting als het gebruik als maat voor interne consistentie kent grote problemen.","Gegeven de samenhang tussen de items en de gebruikelijke aannames over meetfouten kan alpha niet gelijk zijn aan de werkelijke betrouwbaarheid van de testscore.","Alpha staat los van de interne structuur van een test."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'sijtsma-2009-alpha')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'sijtsma2009st');
