SELECT 'start', 'tavakol-dennick-2011-cronbachs-alpha', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'tavakol2011') THEN 'tavakol2011st' ELSE 'tavakol2011' END, 'artikel', 'Making sense of Cronbach''s alpha', '[{"achternaam":"Tavakol","tussenvoegsel":"","voorletters":"M."},{"achternaam":"Dennick","tussenvoegsel":"","voorletters":"R."}]', '', '', 2011, 'en', 'https://doi.org/10.5116/ijme.4dfb.8dfd', '10.5116/ijme.4dfb.8dfd', '{"tijdschrift":"International Journal of Medical Education","jaargang":"2","paginas":"53–55"}', '["statistiek","methode"]', '[]', 'Korte uitleg over wat Cronbach''s alpha meet, welke aannames eronder liggen en hoe je de waarde interpreteert. Alpha hangt af van het aantal items, de samenhang tussen items en de dimensionaliteit, en geldt voor de scores in een specifieke steekproef. De auteurs raden aan alpha per concept te berekenen en bij elke afname opnieuw.', '["Cronbach ontwikkelde alpha in 1951 als maat voor interne consistentie van een test of schaal, uitgedrukt als getal tussen 0 en 1.","In de literatuur lopen de acceptabele waarden uiteen van 0,70 tot 0,95; een alpha boven 0,90 kan wijzen op overbodige items.","Alpha hangt ook af van de lengte van de test; bereken het per concept en niet voor de hele vragenlijst.","Alpha is een eigenschap van de scores in een specifieke steekproef; bereken het bij elke afname opnieuw in plaats van te leunen op gepubliceerde waarden."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'tavakol-dennick-2011-cronbachs-alpha')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'tavakol2011st');
