SELECT 'start', 'tno-2021-duurzame-inzetbaarheid-nl', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'heuvel2021') THEN 'heuvel2021st' ELSE 'heuvel2021' END, 'rapport', 'Duurzame Inzetbaarheid in Nederland 2021: Resultaten van de Monitor DI 2014–2019', '[{"achternaam":"Heuvel","tussenvoegsel":"van den","voorletters":"S."},{"achternaam":"Kraan","tussenvoegsel":"","voorletters":"K."},{"achternaam":"Bouwens","tussenvoegsel":"","voorletters":"L."}]', 'TNO', '', 2021, 'nl', 'https://monitorarbeid.tno.nl/publicaties/duurzame-inzetbaarheid-in-nederland-2021/', '', '{"rapportnummer":"TNO 2021 R11794"}', '["ontwikkeling","verzuim"]', '[]', 'TNO beschrijft hoe het in 2019 stond met de duurzame inzetbaarheid van werknemers in Nederland en hoe die zich sinds 2014 heeft ontwikkeld. Duurzame inzetbaarheid betekent dat mensen nu kunnen werken én ook later kunnen en willen blijven werken. Het rapport vergelijkt jongere en oudere werknemers, laag en hoger opgeleiden, flexwerkers en vaste werknemers, en sectoren. Let op: de cijfers gaan over 2019 en eerder.', '["Duurzame inzetbaarheid betekent dat werkenden nu inzetbaar zijn en ook op langere termijn kunnen en willen blijven werken.","De gemiddelde leeftijd waarop werknemers met pensioen gaan, steeg van 63,8 jaar (2014) naar 65,1 jaar (2019).","Flexwerkers vinden leren net zo belangrijk als vaste werknemers, maar volgen veel minder vaak scholing.","De zorgsector scoort laag op de feitelijke pensioenleeftijd en op de leeftijd tot wanneer werknemers denken door te kunnen werken."]', 'redelijk', 'Publicatie van een kennisinstituut.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'tno-2021-duurzame-inzetbaarheid-nl')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'heuvel2021st');
