SELECT 'start', 'tno-2024-lange-termijn-llo', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'tno2024') THEN 'tno2024st' ELSE 'tno2024' END, 'website', 'Lange termijn effecten van leven lang ontwikkelen', '[]', 'TNO', '', 2024, 'nl', 'https://monitorarbeid.tno.nl/news/lange-termijn-effecten-van-leven-lang-ontwikkelen/', '', '{"sitenaam":"TNO Monitor Arbeid","datum":"2024-01-22","geraadpleegd":"2026-11-27"}', '["ontwikkeling","tevredenheid"]', '[]', 'TNO volgde werknemers zes jaar lang (2016–2021) en keek wat informeel leren (van taken en collega''s), formeel leren (cursussen en opleidingen) en de combinatie drie jaar later opleveren. Vooral informeel leren en de combinatie van informeel en formeel leren hebben positieve effecten, voor werknemers én voor werkgevers. Er zijn geen effecten gevonden op verloop of verzuim. TNO adviseert daarom om meer te investeren in leren op de werkvloer.', '["Het onderzoek gebruikt gegevens van dezelfde werknemers van 2016 tot en met 2021: de leersituatie in 2016–2018 en de uitkomsten in 2021.","Vooral informeel leren en de combinatie van informeel en formeel leren hebben de meeste positieve effecten, bijvoorbeeld op werktevredenheid, promotie en inkomen.","Bij een gunstige informele leersituatie denkt 52% van de medewerkers mee over innovaties, tegen 31% bij een ongunstige leersituatie.","Er zijn geen effecten gevonden van leren op verloop of verzuim in de organisatie."]', 'redelijk', 'Publicatie van een kennisinstituut.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'tno-2024-lange-termijn-llo')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'tno2024st');
