SELECT 'start', 'tno-2025-arbobalans-2024', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'heuvel2025') THEN 'heuvel2025st' ELSE 'heuvel2025' END, 'rapport', 'Arbobalans 2024', '[{"achternaam":"Heuvel","tussenvoegsel":"van den","voorletters":"S. G."},{"achternaam":"Bouwens","tussenvoegsel":"","voorletters":"L."},{"achternaam":"Vroome","tussenvoegsel":"de","voorletters":"E. M. M."}]', 'TNO', '', 2025, 'nl', 'https://monitorarbeid.tno.nl/publicaties/arbobalans-2024/', '', '{"rapportnummer":"TNO 2025 R11108"}', '["werkdruk","verzuim","sociale-veiligheid"]', '[]', 'De Arbobalans 2024 beschrijft de kwaliteit van het werk en de werkgerelateerde gezondheid van werkenden in Nederland, en wat werkgevers daaraan doen. Het rapport gebruikt vooral cijfers uit 2023 en 2024 en kijkt naar trends vanaf 2015. Burn-outklachten en het verzuim zijn gestegen, en verzuim door psychische klachten duurt het langst. De kosten van werkgerelateerd verzuim voor werkgevers zijn sterk toegenomen.', '["Bij werknemers steeg het aandeel met burn-outklachten van 13% in 2015 naar 19% in 2023.","De kosten voor werkgevers van loondoorbetaling bij werkgerelateerd verzuim stegen van 5,1 miljard euro (2015) naar 8,3 miljard euro (2023); 4,9 miljard daarvan kwam in 2023 door psychosociale arbeidsbelasting.","Werknemers die te maken hebben met ongewenst gedrag door collega''s of leidinggevenden, hebben een 1,5 keer zo grote kans dat zij in het afgelopen jaar hebben verzuimd.","Meer organisaties hebben een RI&E: 64% in 2024, tegen 46% in 2014."]', 'redelijk', 'Publicatie van een kennisinstituut.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'tno-2025-arbobalans-2024')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'heuvel2025st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'tno-2026-factsheet-werkstress', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'tno2026') THEN 'tno2026st' ELSE 'tno2026' END, 'rapport', 'Werkstress: factsheet Week van de werkstress 2026', '[]', 'TNO', '', 2026, 'nl', 'https://monitorarbeid.tno.nl/publicaties/factsheet-week-van-de-werkstress-2026/', '', '{}', '["werkdruk","verzuim","sociale-veiligheid"]', '[]', 'Dit is een korte factsheet van TNO met cijfers over werkstress, zowel volgens werknemers als volgens werkgevers. Hij gaat over stressvol werk, burn-outklachten, conflicten en ongewenst gedrag, en over verzuimdagen en verzuimkosten door psychosociale arbeidsbelasting. Ook staan er cijfers in over psychologische veiligheid en over maatregelen die werkgevers nemen.', '["15% van de werknemers heeft stressvol werk: hoge taakeisen en weinig autonomie (NEA 2025). Dat komt het meest voor in de horeca, het onderwijs en de zorg.","Ruim 1,7 miljoen werknemers (21%) hebben last van burn-outklachten of psychische vermoeidheid (NEA 2025); in 2015 was dat 13%.","In 2024 verzuimden werknemers 13,5 miljoen dagen door psychosociale arbeidsbelasting, waarvan 8,8 miljoen door te hoge werkdruk. De totale verzuimkosten door psychosociale arbeidsbelasting waren voor werkgevers 4,8 miljard euro.","34% van de werkgevers ziet hoge werkdruk als een van de belangrijkste arbeidsrisico''s (WEA 2026)."]', 'redelijk', 'Publicatie van een kennisinstituut.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'tno-2026-factsheet-werkstress')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'tno2026st');
