SELECT 'start', 'tno-cbs-2026-nea2025', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'dam2026') THEN 'dam2026st' ELSE 'dam2026' END, 'rapport', 'Nationale Enquête Arbeidsomstandigheden 2025 – Resultaten in vogelvlucht', '[{"achternaam":"Dam","tussenvoegsel":"van","voorletters":"L. M. C."},{"achternaam":"Pleijers","tussenvoegsel":"","voorletters":"A. J. S. F."},{"achternaam":"Kraan","tussenvoegsel":"","voorletters":"K. O."},{"achternaam":"Souren","tussenvoegsel":"","voorletters":"M. H. J."},{"achternaam":"Hulsegge","tussenvoegsel":"","voorletters":"G."}]', 'TNO en CBS', '', 2026, 'nl', 'https://monitorarbeid.tno.nl/publicaties/nationale-enquete-arbeidsomstandigheden-2025-resultaten-in-vogelvlucht/', '', '{}', '["werkdruk","verzuim","sociale-veiligheid"]', '[]', 'Dit is het eerste overzicht van de resultaten van de Nationale Enquête Arbeidsomstandigheden (NEA) 2025. Ruim 53.000 werknemers vulden eind 2025 de vragenlijst in. Het rapport gaat onder meer over werkdruk en burn-outklachten, ongewenst gedrag, gezondheid en verzuim, loopbaan en leren. Achterin staan tabellen met uitsplitsingen naar geslacht, leeftijd en sector.', '["Het aandeel werknemers met burn-outklachten steeg van 19% in 2023 naar 21% in 2025. In 2015 was dat nog 13%.","Het verzuim volgens de werknemers zelf bleef in 2025 bijna gelijk (4,9%, tegen 4,8% in 2024). Volgens de opgave van bedrijven aan het CBS steeg het verzuim in 2025 licht, van 5,2% naar 5,4%.","In 2025 kreeg 17% van de werknemers in de twaalf maanden daarvoor te maken met ongewenst gedrag op het werk. Dat kwam vaker van klanten (11%) dan van collega''s (5,4%) of leidinggevenden (2,9%).","37% van de werknemers vond in 2025 dat er (extra) maatregelen nodig zijn tegen werkdruk en werkstress."]', 'redelijk', 'Publicatie van een kennisinstituut.', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'tno-cbs-2026-nea2025')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'dam2026st');
