SELECT 'start', 'van-dierendonck-2011-dienend-leiderschap', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'dierendonck2011') THEN 'dierendonck2011st' ELSE 'dierendonck2011' END, 'artikel', 'Servant Leadership: A Review and Synthesis', '[{"achternaam":"Dierendonck","tussenvoegsel":"van","voorletters":"D."}]', '', '', 2011, 'en', 'https://doi.org/10.1177/0149206310380462', '10.1177/0149206310380462', '{"tijdschrift":"Journal of Management","jaargang":"37","nummer":"4","paginas":"1228–1261"}', '["leiderschap"]', '[]', 'Overzichtsartikel over dienend leiderschap. Het behandelt de historische achtergrond, de kernkenmerken, de beschikbare meetinstrumenten en de onderzoeksresultaten tot dat moment, en eindigt met een overkoepelend conceptueel model. Volgens de auteur tonen leiders dienend leiderschap wanneer zij de motivatie om te leiden combineren met de behoefte om te dienen. Dat blijkt onder meer uit het ontwikkelen en empoweren van medewerkers, bescheidenheid, authenticiteit en richting geven.', '["Dienend leiderschap blijkt uit het empoweren en ontwikkelen van mensen, bescheidenheid, authenticiteit, acceptatie van anderen, rentmeesterschap en richting geven.","Dienend leiders combineren de motivatie om te leiden met de behoefte om te dienen.","Het artikel geeft een overzicht van de achtergrond, de kenmerken, de meetinstrumenten en de onderzoeksresultaten over dienend leiderschap."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'van-dierendonck-2011-dienend-leiderschap')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'dierendonck2011st');
INSERT INTO bronnen (collectie, sleutel, citeersleutel, soort, titel, auteurs, organisatie, afkorting, jaar, taal, url, doi, details, onderwerpen, trefwoorden, samenvatting, kernpunten, betrouwbaarheid, betrouwbaarheid_toelichting, aangemaakt_op, bijgewerkt_op)
SELECT 'start', 'van-knippenberg-de-dreu-homan-2004-diversiteit-prestatie', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'knippenberg2004') THEN 'knippenberg2004st' ELSE 'knippenberg2004' END, 'artikel', 'Work Group Diversity and Group Performance: An Integrative Model and Research Agenda.', '[{"achternaam":"Knippenberg","tussenvoegsel":"van","voorletters":"D."},{"achternaam":"Dreu","tussenvoegsel":"de","voorletters":"C. K. W."},{"achternaam":"Homan","tussenvoegsel":"","voorletters":"A. C."}]', '', '', 2004, 'en', 'https://doi.org/10.1037/0021-9010.89.6.1008', '10.1037/0021-9010.89.6.1008', '{"tijdschrift":"Journal of Applied Psychology","jaargang":"89","nummer":"6","paginas":"1008–1022"}', '["sociale-veiligheid"]', '[]', 'Onderzoek naar het verband tussen diversiteit in werkgroepen en groepsprestaties leverde tegenstrijdige resultaten op. Daarom stellen de auteurs het categorisatie-elaboratiemodel (CEM) voor. Dat model herdefinieert het informatie- en besluitvormingsperspectief en een sociaal perspectief op diversiteit en brengt ze samen in één kader. Alleen het begin van de samenvatting kon worden gecontroleerd.', '["Onderzoek naar diversiteit in werkgroepen en prestaties gaf tot dan toe tegenstrijdige resultaten.","Het categorisatie-elaboratiemodel (CEM) brengt het informatie- en besluitvormingsperspectief en een sociaal perspectief op diversiteit samen."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'van-knippenberg-de-dreu-homan-2004-diversiteit-prestatie')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'knippenberg2004st');
