SELECT 'start', 'vanderklink-2016-duurzame-inzetbaarheid', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'klink2016') THEN 'klink2016st' ELSE 'klink2016' END, 'artikel', 'Sustainable employability – definition, conceptualization, and implications: A perspective based on the capability approach', '[{"achternaam":"Klink","tussenvoegsel":"van der","voorletters":"J. J. L."},{"achternaam":"Bültmann","tussenvoegsel":"","voorletters":"U."},{"achternaam":"Burdorf","tussenvoegsel":"","voorletters":"A."},{"achternaam":"Schaufeli","tussenvoegsel":"","voorletters":"W. B."},{"achternaam":"Zijlstra","tussenvoegsel":"","voorletters":"F. R. H."},{"achternaam":"Abma","tussenvoegsel":"","voorletters":"F. I."},{"achternaam":"Brouwer","tussenvoegsel":"","voorletters":"S."},{"achternaam":"Wilt","tussenvoegsel":"van der","voorletters":"G. J."}]', '', '', 2016, 'en', 'https://doi.org/10.5271/sjweh.3531', '10.5271/sjweh.3531', '{"tijdschrift":"Scandinavian Journal of Work, Environment & Health","jaargang":"42","nummer":"1","paginas":"71–79"}', '["verzuim"]', '[]', 'Conceptueel artikel van Nederlandse onderzoekers dat een nieuw model van duurzame inzetbaarheid voorstelt, gebaseerd op de capability-benadering. Het model wil recht doen aan de complexiteit van hedendaags werk en legt de nadruk op werkgerelateerde waarden. In deze sessie was alleen een ingekort abstract beschikbaar; de uitwerking van het model is niet verder gecontroleerd.', '["Het artikel stelt een nieuw model van duurzame inzetbaarheid voor, gebaseerd op de capability-benadering.","Het model houdt rekening met de complexiteit van hedendaags werk en legt de nadruk op werkgerelateerde waarden."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'vanderklink-2016-duurzame-inzetbaarheid')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'klink2016st');
