SELECT 'start', 'verkuil-atasayi-molendijk-2015-pesten', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'verkuil2015') THEN 'verkuil2015st' ELSE 'verkuil2015' END, 'artikel', 'Workplace Bullying and Mental Health: A Meta-Analysis on Cross-Sectional and Longitudinal Data', '[{"achternaam":"Verkuil","tussenvoegsel":"","voorletters":"B."},{"achternaam":"Atasayi","tussenvoegsel":"","voorletters":"S."},{"achternaam":"Molendijk","tussenvoegsel":"","voorletters":"M. L."}]', '', '', 2015, 'en', 'https://doi.org/10.1371/journal.pone.0135225', '10.1371/journal.pone.0135225', '{"tijdschrift":"PLOS ONE","jaargang":"10","nummer":"8","artikelnummer":"e0135225"}', '["sociale-veiligheid"]', '[]', 'Meta-analyse van cross-sectionele en longitudinale studies naar pesten op het werk en mentale gezondheid. Pesten hangt samen met meer depressieve klachten, angst en stressgerelateerde klachten, ook over de tijd. Omgekeerd hangen bestaande mentale klachten ook samen met later gepest worden; het verband werkt dus in twee richtingen. Alle gegevens kwamen uit zelfrapportage.', '["Cross-sectioneel hangt pesten op het werk samen met depressieve klachten (r = .28), angst (r = .34) en stressgerelateerde psychische klachten (r = .37).","Longitudinaal hangt pesten samen met latere mentale klachten (r = 0,21).","Mentale klachten bij de start hangen ook samen met later gepest worden (r = 0,18): het verband werkt in twee richtingen.","Beperking: alle data waren zelfrapportage, waardoor rapportagebias mogelijk is."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'verkuil-atasayi-molendijk-2015-pesten')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'verkuil2015st');
