SELECT 'start', 'west-2021-welch-t-toets', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'west2021') THEN 'west2021st' ELSE 'west2021' END, 'artikel', 'Best practice in statistics: Use the Welch t -test when testing the difference between two groups', '[{"achternaam":"West","tussenvoegsel":"","voorletters":"R. M."}]', '', '', 2021, 'en', 'https://doi.org/10.1177/0004563221992088', '10.1177/0004563221992088', '{"tijdschrift":"Annals of Clinical Biochemistry: International Journal of Laboratory Medicine","jaargang":"58","nummer":"4","paginas":"267–269"}', '["statistiek"]', '[]', 'Artikel over goede statistische praktijk bij het vergelijken van twee groepen metingen, geschreven voor klinisch biochemici. De auteur geeft uitleg over de Welch t-toets, die op subtiele maar belangrijke punten verschilt van Student''s t-toets en in meer situaties geldig is. Zijn advies is om bij twee groepen de Welch-toets te gebruiken in plaats van Student''s t-toets.', '["Advies: gebruik de Welch t-toets in plaats van Student''s t-toets wanneer je het verschil tussen twee groepen toetst.","De Welch t-toets verschilt subtiel maar belangrijk van Student''s t-toets en is in een breder scala aan situaties geldig."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'west-2021-welch-t-toets')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'west2021st');
