SELECT 'start', 'williams-mcdaniel-nguyen-2006-salaristevredenheid', CASE WHEN EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'williams2006') THEN 'williams2006st' ELSE 'williams2006' END, 'artikel', 'A meta-analysis of the antecedents and consequences of pay level satisfaction.', '[{"achternaam":"Williams","tussenvoegsel":"","voorletters":"M. L."},{"achternaam":"McDaniel","tussenvoegsel":"","voorletters":"M. A."},{"achternaam":"Nguyen","tussenvoegsel":"","voorletters":"N. T."}]', '', '', 2006, 'en', 'https://doi.org/10.1037/0021-9010.91.2.392', '10.1037/0021-9010.91.2.392', '{"tijdschrift":"Journal of Applied Psychology","jaargang":"91","nummer":"2","paginas":"392–413"}', '["arbeidsvoorwaarden","tevredenheid"]', '[]', 'Meta-analyse van 28 factoren die samenhangen met tevredenheid over de hoogte van het salaris. De analyse omvat 240 steekproeven uit 203 studies over een periode van 35 jaar. De resultaten zijn ingedeeld in primaire determinanten, antecedenten, correlaten en uitkomsten van salaristevredenheid. Alleen het begin van de samenvatting kon worden gecontroleerd.', '["De meta-analyse betreft 28 correlaten van tevredenheid met het salarisniveau, uit 240 steekproeven en 203 studies over 35 jaar.","De resultaten zijn ingedeeld in vier categorieën: primaire determinanten, antecedenten, correlaten en uitkomsten van salaristevredenheid."]', 'hoog', 'Wetenschappelijk artikel, beoordeeld door andere onderzoekers (peer review).', '2026-11-27T00:00:00.000Z', '2026-11-27T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM bronnen WHERE sleutel = 'williams-mcdaniel-nguyen-2006-salaristevredenheid')
  AND NOT EXISTS (SELECT 1 FROM bronnen WHERE citeersleutel = 'williams2006st');
